import Link from "next/link";
import { requireAdmin, hasPermission } from "@/lib/admin/rbac";
import { listTestimonials, listFaqs } from "@/lib/admin/content";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import adminStyles from "../admin.module.css";
import styles from "./content.module.css";

export const metadata = {
  title: "Website Content | Admin | Pexpacks",
};

export default async function ContentHubPage() {
  const session = await requireAdmin({ permission: "content.view" });
  const [testimonials, faqs] = await Promise.all([listTestimonials(), listFaqs()]);
  const canManage = hasPermission(session, "content.manage");

  const cards = [
    {
      href: "/admin/content/testimonials",
      title: "Testimonials",
      text: "Manage the quotes shown in the homepage testimonial marquee.",
      count: `${testimonials.filter((t) => t.visible).length} live of ${testimonials.length}`,
    },
    {
      href: "/admin/content/faqs",
      title: "FAQs",
      text: "Manage the questions and answers shown on the FAQ page and site sections.",
      count: `${faqs.filter((f) => f.visible).length} live of ${faqs.length}`,
    },
    {
      href: "/admin/content/sections",
      title: "Content sections",
      text: "Edit homepage, footer and SEO copy that appears across the site.",
      count: "5 sections",
    },
  ];

  return (
    <div className={adminStyles.adminContainer}>
      <AdminPageHeader
        title="Website Content"
        subtitle="Manage testimonials, FAQs, and site-wide marketing copy."
      />

      <div className={styles.grid}>
        {cards.map((card) => (
          <Link key={card.href} href={card.href} className={styles.hubCard}>
            <h2 className={styles.hubCardTitle}>{card.title}</h2>
            <p className={styles.hubCardText}>{card.text}</p>
            <span className={styles.hubCardCount}>{card.count}</span>
          </Link>
        ))}
      </div>
    </div>
  );
}

﻿import { Package } from "lucide-react";
import { requireAdmin, hasPermission } from "@/lib/admin/rbac";
import {
  listPurchaseOrdersForReceivins,
} from "@/lib/admin/operations";
import { createSupplierReceiptAction } from "../../operations-actions";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import adminStyles from "@/app/admin/admin.module.css";
import { StatusBadge } from "@/components/admin/ui/StatusBadge";

export const dynamic = "force-dynamic";

export default async function ReceivingPage() {
  const [session, purchaseOrders] = await Promise.all([
    requireAdmin({ permission: "procurement.view" }),
    listPurchaseOrdersForReceiving(),
  ]);

  return (
    <div className={adminStyles.page}>
      <AdminPageHeader
        backHref="/admin/procurement"
        backLabel="Back to Procurement"
        title="Receive Goods"
        subtitle="Record incoming stock from suppliers against purchase orders."
      />

      {purchaseOrders.length === 0 ? (
        <div className={adminStyles.formPanel}>
          <Package aria-hidden="true" />
          <p>No purchase orders are awaiting receipt.</p>
        </div>
      ) : (
        purchaseOrders.map((po) => {
          const totalOrdered = po.supplier_purchase_items.reduce(
            (sum, item) => sum + item.ordered_quantity,
            0,
          );
          const totalReceived = po.supplier_purchase_items.reduce(
            (sum, item) => sum + item.received_quantity,
            0,
          );
          const percentReceived = totalOrdered
            ? Math.round((totalReceived / totalOrdered) * 100)
            : 0;

          return (
            <section key={po.id} className={adminStyles.formPanel}>
              <h2>
                {po.purchase_order_number}
                <StatusBadge
                  status={po.status}
                  tone={po.status === "received" ? "emerald" : po.status === "partially_received" ? "amber" : "slate"}
                  className={adminStyles.ml8}
                />
              </h2>
              <p className={adminStyles.muted}>
                {po.suppliers?.name || "Unknown supplier"} ·{" "}
                {po.expected_on
                  ? `Expected ${new Date(po.expected_on).toLocaleDateString("en-ZA")}`
                  : "No expected date"}
                · {percentReceived}% received
              </p>

              <div className={adminStyles.tableCard}>
                <div className={adminStyles.tableWrapper}>
                  <table className={adminStyles.table}>
                    <thead>
                      <tr>
                        <th>SKU</th>
                        <th>Product</th>
                        <th>Ordered</th>
                        <th>Previously Received</th>
                        <th>Receiving Now</th>
                      </tr>
                    </thead>
                    <tbody>
                      {po.supplier_purchase_items.map((item) => (
                        <tr key={item.id}>
                          <td className={adminStyles.mono}>
                            {item.master_products?.sku || "-"}
                          </td>
                          <td>{item.master_products?.name || "Unknown"}</td>
                          <td>{item.ordered_quantity}</td>
                          <td>{item.received_quantity}</td>
                          <td>
                            {hasPermission(session, "procurement.manage") ? (
                              <input
                                className={`${adminStyles.field} ${adminStyles.w80}`}
                                type="number"
                                min="0"
                                max={item.ordered_quantity - item.received_quantity}
                                defaultValue="0"
                                name={`received_${item.id}`}
                              />
                            ) : (
                              item.received_quantity
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              {hasPermission(session, "procurement.manage") ? (
                <form
                  action={createSupplierReceiptAction}
                  className={`${adminStyles.formGrid} ${adminStyles.mt16}`}
                >
                  <input type="hidden" name="purchaseOrderId" value={po.id} />
                  <input
                    className={adminStyles.field}
                    name="reference"
                    placeholder="Delivery note / invoice ref"
                  />
                  <input
                    className={`${adminStyles.field} ${adminStyles.wide}`}
                    name="notes"
                    placeholder="Notes (condition, discrepancies, etc.)"
                  />
                  <button className={adminStyles.button}>Record receipt</button>
                </form>
              ) : null}
            </section>
          );
        })
      )}
    </div>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { pdf } from "@react-pdf/renderer";
import React from "react";
import { createSupabaseAdminClient } from "@/lib/supabase/admin";
import {
  createQuotation,
  updateQuotationStatus,
  convertQuotationToOrder,
  getQuotation,
  updateQuotationPdfPath,
  type QuotationInput,
  type QuotationStatus,
} from "@/lib/admin/quotations";
import { getQuotationSettings } from "@/lib/admin/quotation-settings";
import { QuotationPdfDocument } from "@/components/pdf/QuotationPdfDocument";
import { getPack } from "@/lib/admin/packs";

/**
 * Generate PDF buffer and upload to Supabase Storage
 */
async function generateAndUploadPdf(quotationId: string): Promise<string | null> {
  try {
    const quotation = await getQuotation(quotationId);
    if (!quotation) return null;

    const settings = await getQuotationSettings();
    const formattedAddress = `${settings.address.address_line1}, ${
      settings.address.address_line2 ? settings.address.address_line2 + ", " : ""
    }${settings.address.suburb}, ${settings.address.city}, ${settings.address.postal_code}, ${settings.address.country}`;

    let preparedBy: string | null = null;
    if (quotation.notes) {
      const match = quotation.notes.match(/Prepared by:\s*([^\n\r]+)/i);
      if (match) {
        preparedBy = match[1].trim();
      }
    }

    const pdfData = {
      quote_number: quotation.quote_number,
      created_at: new Date(quotation.created_at).toLocaleDateString("en-ZA"),
      valid_until: new Date(quotation.valid_until).toLocaleDateString("en-ZA"),
      status: quotation.status,
      prepared_by: preparedBy,
      recipient_name: quotation.recipient_name,
      recipient_email: quotation.recipient_email,
      recipient_phone: quotation.recipient_phone,
      school_name: quotation.school?.name,
      school_address: quotation.school
        ? `${quotation.school.city || "Johannesburg"}, ${quotation.school.province || "Gauteng"}`
        : null,
      subtotal: quotation.subtotal,
      vat_rate: quotation.vat_rate,
      vat_amount: quotation.vat_amount,
      total_amount: quotation.total_amount,
      notes: quotation.notes,
      items: (quotation.items || []).map((item) => ({
        item_title: item.item_title,
        sku: item.sku,
        unit: item.unit,
        quantity: item.quantity,
        unit_price: item.unit_price,
        total_price: item.total_price,
      })),
      company: {
        registered_name: settings.business.registered_name,
        trading_name: settings.business.trading_name,
        reg_number: settings.business.reg_number,
        vat_number: settings.business.vat_number,
        address_text: formattedAddress,
        phone: settings.contacts.main_phone,
        email: `${settings.contacts.quotation_email} | ${settings.contacts.general_email}`,
        website: settings.business.website,
        bank_name: settings.banking.bank_name,
        account_holder: settings.banking.account_holder,
        account_type: settings.banking.account_type,
        account_number: settings.banking.account_number,
        branch_code: settings.banking.branch_code,
        default_terms: settings.notesTerms.terms_and_conditions,
      },
    };

    // Render PDF buffer
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const element = React.createElement(QuotationPdfDocument, { data: pdfData }) as any;
    const documentBuffer = await pdf(element).toBuffer();

    const admin = createSupabaseAdminClient();
    const filePath = `quotes/${quotation.quote_number}_${Date.now()}.pdf`;

    const { error: uploadError } = await admin.storage
      .from("quotations")
      .upload(filePath, documentBuffer, {
        contentType: "application/pdf",
        upsert: true,
      });

    if (uploadError) {
      console.error("[quotations] storage upload failed:", uploadError);
      return null;
    }

    const { data: publicUrlData } = admin.storage
      .from("quotations")
      .getPublicUrl(filePath);

    const storagePath = publicUrlData?.publicUrl || filePath;

    // Update quote record with PDF path, status, and bumped version
    await updateQuotationPdfPath(quotationId, storagePath);

    return storagePath;
  } catch (err) {
    console.error("[quotations] PDF generation error:", err);
    return null;
  }
}

/**
 * Create quotation server action
 */
export async function createQuotationAction(
  input: QuotationInput,
  status: QuotationStatus = "draft"
): Promise<{ ok: boolean; id?: string; quoteNumber?: string; error?: string }> {
  const result = await createQuotation(input, status);
  if (!result.ok || !result.quotation) {
    return { ok: false, error: result.error || "Failed to create quotation" };
  }

  const quoteId = result.quotation.id;
  const quoteNumber = result.quotation.quote_number;

  // Background render PDF
  void generateAndUploadPdf(quoteId);

  revalidatePath("/admin/quotations");
  revalidatePath("/admin/quotations", "layout");

  return { ok: true, id: quoteId, quoteNumber };
}

/**
 * Delete quotation server action
 */
export async function deleteQuotationAction(
  id: string
): Promise<{ ok: boolean; error?: string }> {
  const { deleteQuotation } = await import("@/lib/admin/quotations");
  const result = await deleteQuotation(id);
  if (!result.ok) {
    return { ok: false, error: result.error };
  }

  revalidatePath("/admin/quotations");
  return { ok: true };
}

/**
 * Update quotation status server action
 */
export async function updateQuotationStatusAction(
  id: string,
  status: QuotationStatus
): Promise<{ ok: boolean; error?: string }> {
  const result = await updateQuotationStatus(id, status);
  if (!result.ok) {
    return { ok: false, error: result.error };
  }

  revalidatePath("/admin/quotations");
  revalidatePath(`/admin/quotations/${id}`);
  return { ok: true };
}

/**
 * Convert quotation to order server action
 */
export async function convertQuotationToOrderAction(
  quotationId: string
): Promise<{ ok: boolean; orderId?: string; orderReference?: string; error?: string }> {
  const result = await convertQuotationToOrder(quotationId);
  if (!result.ok) {
    return { ok: false, error: result.error };
  }

  revalidatePath("/admin/quotations");
  revalidatePath(`/admin/quotations/${quotationId}`);
  revalidatePath("/admin/orders");
  revalidatePath("/admin/procurement");

  return {
    ok: true,
    orderId: result.orderId,
    orderReference: result.orderReference,
  };
}

/**
 * Regenerate / get PDF URL
 */
export async function regenerateQuotationPdfAction(
  quotationId: string
): Promise<{ ok: boolean; pdfUrl?: string; error?: string }> {
  const pdfUrl = await generateAndUploadPdf(quotationId);
  if (!pdfUrl) {
    return { ok: false, error: "Failed to generate PDF letterhead." };
  }
  revalidatePath(`/admin/quotations/${quotationId}`);
  return { ok: true, pdfUrl };
}

/**
 * Import line items from an existing school grade pack
 */
export async function importSchoolPackItemsAction(
  packId: string
): Promise<{
  ok: boolean;
  packTitle?: string;
  items?: Array<{
    master_product_id: string | null;
    item_title: string;
    sku: string | null;
    unit: string;
    quantity: number;
    unit_price: number;
  }>;
  error?: string;
}> {
  try {
    const { pack, items } = await getPack(packId);
    if (!pack || !items) {
      return { ok: false, error: "School pack not found." };
    }

    const converted = items.map((item) => ({
      master_product_id: item.product_id || null,
      item_title: item.name,
      sku: item.sku || null,
      unit: "Each",
      quantity: Number(item.quantity || 1),
      unit_price: Number(item.unit_price || 0),
    }));

    return {
      ok: true,
      packTitle: pack.title,
      items: converted,
    };
  } catch (err: any) {
    console.error("[quotations] importSchoolPackItemsAction failed:", err);
    return { ok: false, error: err?.message || "Failed to load pack items." };
  }
}

/**
 * Fetch list of packs for a specific school
 */
export async function listSchoolPacksForQuotation(
  schoolId: string
): Promise<Array<{ id: string; title: string; price: number }>> {
  const admin = createSupabaseAdminClient();
  const { data, error } = await admin
    .from("school_packs")
    .select("id, title, price")
    .eq("school_id", schoolId)
    .order("sort_order", { ascending: true })
    .order("title", { ascending: true });

  if (error || !data) return [];
  return data.map((p) => ({ id: p.id, title: p.title, price: Number(p.price || 0) }));
}

import { redirect } from "next/navigation";

export const dynamic = "force-dynamic";

interface SettingsTabRouteProps {
  params: Promise<{ tab: string }>;
}

export default async function SettingsTabRoutePage({ params }: SettingsTabRouteProps) {
  redirect("/admin/settings");
}

"use server";

import { revalidatePath } from "next/cache";
import { getAdminUser, hasPermission } from "@/lib/admin/rbac";
import {
  createOperationalTask,
  updateOperationalTaskStatus,
  listTaskComments,
  createTaskComment,
  getTask,
} from "@/lib/admin/operations";

async function assertAdminSession(permission: string) {
  const session = await getAdminUser();
  if (!session || !hasPermission(session, permission as any)) {
    throw new Error("Unauthorized: Insufficient permissions.");
  }
  return session;
}

export async function createTaskAction(formData: FormData) {
  const session = await assertAdminSession("tasks.manage");
  const title = String(formData.get("title") || "").trim();
  const description = String(formData.get("description") || "").trim();
  const priority = String(formData.get("priority") || "normal");
  const dueAt = String(formData.get("due_at") || "");
  const entityType = String(formData.get("entity_type") || "");
  const entityId = String(formData.get("entity_id") || "");

  if (!title) {
    return { ok: false, error: "Title is required." };
  }

  try {
    const task = await createOperationalTask({
      title,
      description: description || undefined,
      priority,
      dueAt: dueAt || undefined,
      entityType: entityType || undefined,
      entityId: entityId || undefined,
      createdBy: session.user.id,
    });
    revalidatePath("/admin/tasks");
    return { ok: true, task };
  } catch (err: any) {
    return { ok: false, error: err.message || "Failed to create task." };
  }
}

export async function updateTaskStatusAction(taskId: string, status: string) {
  await assertAdminSession("tasks.manage");
  try {
    await updateOperationalTaskStatus(taskId, status);
    revalidatePath("/admin/tasks");
    return { ok: true };
  } catch (err: any) {
    return { ok: false, error: err.message || "Failed to update task status." };
  }
}

export async function loadTaskActivitiesAction(taskId: string) {
  await assertAdminSession("tasks.view");
  try {
    const comments = await listTaskComments(taskId);
    return { ok: true, comments };
  } catch (err: any) {
    return { ok: false, comments: [] };
  }
}

export async function addTaskCommentAction(taskId: string, body: string) {
  const session = await assertAdminSession("tasks.view");
  if (!body.trim()) {
    return { ok: false, error: "Comment body cannot be empty." };
  }

  try {
    const comment = await createTaskComment({
      taskId,
      authorId: session.user.id,
      body: body.trim(),
    });
    return { ok: true, comment };
  } catch (err: any) {
    return { ok: false, error: err.message || "Failed to add comment." };
  }
}

export async function approveTaskAction(taskId: string, notes?: string) {
  const session = await assertAdminSession("approvals.manage");
  try {
    const task = await getTask(taskId);
    if (!task) {
      return { ok: false, error: "Task not found." };
    }
    if (task.status === "completed") {
      return { ok: true, alreadyCompleted: true };
    }

    // Transactional status update and comment logging
    await updateOperationalTaskStatus(taskId, "completed");
    await createTaskComment({
      taskId,
      authorId: session.user.id,
      body: `Action approved and marked as completed by ${session.user.email || "Administrator"}.${notes ? ` Notes: ${notes}` : ""}`,
    });

    revalidatePath("/admin/tasks");
    return { ok: true };
  } catch (err: any) {
    return { ok: false, error: err.message || "Failed to approve task." };
  }
}

import { ArrowLeft } from "lucide-react";
import { notFound } from "next/navigation";
import {
  requireAdmin,
  hasPermission,
  displayName,
  type PermissionKey,
} from "@/lib/admin/rbac";
import {
  getUser,
  listRoles,
  getUserPermissionKeys,
  isBanned,
} from "@/lib/admin/users";
import { permissionGroups } from "@/lib/admin/roles";
import { UserRolesForm } from "@/components/admin/users/UserRolesForm";
import {
  UserPermissionsForm,
  type PermissionOption,
} from "@/components/admin/users/UserPermissionsForm";
import { ConfirmButton } from "@/components/admin/ConfirmButton";
import {
  deactivateUserAction,
  reactivateUserAction,
  deleteUserAction,
} from "../actions";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { AdminButton } from "@/components/admin/ui/AdminButton";
import { StatusBadge } from "@/components/admin/ui/StatusBadge";
import adminStyles from "../../admin.module.css";
import styles from "../users.module.css";

interface UserDetailPageProps {
  params: Promise<{ id: string }>;
}

function formatDateTime(value: string | null | undefined): string {
  if (!value) return "—";
  return new Date(value).toLocaleString("en-ZA", {
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export default async function UserDetailPage({ params }: UserDetailPageProps) {
  const session = await requireAdmin({ permission: "users.view" });
  const { id } = await params;
  const [user, roles, overrides] = await Promise.all([
    getUser(id),
    listRoles(),
    getUserPermissionKeys(id),
  ]);
  if (!user) notFound();

  const banned = isBanned(user);
  const canEdit = hasPermission(session, "users.edit");
  const canDeactivate = hasPermission(session, "users.deactivate");
  const canDelete = hasPermission(session, "users.delete");
  const isSelf = user.id === session.user.id;

  const permissionOptions: PermissionOption[] = [];
  for (const group of permissionGroups()) {
    for (const item of group.items) {
      permissionOptions.push({ key: item.key as PermissionKey, name: item.name, group: group.group });
    }
  }

  const userStatus = banned ? "banned" : user.last_sign_in_at ? "active" : "pending";

  return (
    <div className={adminStyles.adminContainer}>
      <AdminPageHeader
        title={displayName(user)}
        subtitle={`Email: ${user.email ?? "—"} • User ID: ${user.id}`}
        actions={
          <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
            <StatusBadge status={userStatus} showDot />
            <AdminButton
              href="/admin/users"
              variant="secondary"
              icon={<ArrowLeft size={14} />}
            >
              Back to Users
            </AdminButton>
          </div>
        }
      />

      <div className={styles.detailMeta}>
        <div className={styles.metaItem}>
          <div className={styles.metaLabel}>Email</div>
          <div className={styles.metaValue}>{user.email ?? "—"}</div>
        </div>
        <div className={styles.metaItem}>
          <div className={styles.metaLabel}>Status</div>
          <div className={styles.metaValue}>
            <StatusBadge status={userStatus} showDot />
          </div>
        </div>
        <div className={styles.metaItem}>
          <div className={styles.metaLabel}>Joined</div>
          <div className={styles.metaValue}>{formatDateTime(user.created_at)}</div>
        </div>
        <div className={styles.metaItem}>
          <div className={styles.metaLabel}>Last sign in</div>
          <div className={styles.metaValue}>{formatDateTime(user.last_sign_in_at)}</div>
        </div>
        <div className={styles.metaItem}>
          <div className={styles.metaLabel}>Roles</div>
          <div className={styles.roleChips}>
            {user.roleSlugs.length > 0 ? (
              user.roleSlugs.map((slug) => (
                <span
                  key={slug}
                  className={`${styles.roleChip} ${slug === "super_admin" ? styles.roleChipSuper : ""}`}
                >
                  {slug.replace(/_/g, " ")}
                </span>
              ))
            ) : (
              <span className={styles.roleChipNone}>No roles assigned</span>
            )}
          </div>
        </div>
      </div>

      <div className={styles.sectionGrid}>
        <div className={styles.sectionCard}>
          <h2 className={styles.sectionTitle}>Assigned roles</h2>
          <p className={styles.sectionDesc}>
            Roles bundle permissions. Users inherit all permissions from their assigned roles.
          </p>
          <UserRolesForm
            userId={user.id}
            roles={roles}
            assigned={user.roleIds}
          />
        </div>

        <div className={styles.sectionCard}>
          <h2 className={styles.sectionTitle}>Permission overrides</h2>
          <p className={styles.sectionDesc}>
            Grant additional permissions to this specific user beyond their role assignments.
          </p>
          <UserPermissionsForm
            userId={user.id}
            permissions={permissionOptions}
            overrides={overrides}
          />
        </div>
      </div>

      {!isSelf && (canDeactivate || canDelete) ? (
        <div className={styles.dangerZone}>
          <h2 className={styles.dangerTitle}>Danger zone</h2>
          <p className={styles.dangerDesc}>
            Deactivating prevents the user from signing in. Deleting removes the user permanently.
          </p>
          <div className={styles.dangerActions}>
            {canDeactivate ? (
              banned ? (
                <form action={reactivateUserAction.bind(null, user.id)}>
                  <ConfirmButton
                    label="Reactivate user"
                    title="Reactivate user"
                    confirmText={`Allow ${displayName(user)} to sign in again?`}
                    busyLabel="Reactivating…"
                    className={`${adminStyles.rowButton} ${styles.dangerBtnReactivate}`}
                  />
                </form>
              ) : (
                <form action={deactivateUserAction.bind(null, user.id)}>
                  <ConfirmButton
                    label="Deactivate user"
                    title="Deactivate user"
                    confirmText={`Suspend ${displayName(user)} from signing in?`}
                    busyLabel="Deactivating…"
                    className={`${adminStyles.rowButton} ${styles.dangerBtnDeactivate}`}
                  />
                </form>
              )
            ) : null}

            {canDelete ? (
              <form action={deleteUserAction.bind(null, user.id)}>
                <ConfirmButton
                  label="Delete user"
                  title="Delete user"
                  confirmText={`Permanently delete ${displayName(user)}? This action cannot be undone.`}
                  busyLabel="Deleting…"
                  className={`${adminStyles.rowButton} ${adminStyles.rowButtonDelete}`}
                />
              </form>
            ) : null}
          </div>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { usePackTrayStore } from "@/store/usePackTrayStore";
import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/Button";
import { formatCurrency } from "@/lib/formatCurrency";
import { PEXCOVER_PRICE } from "@/lib/constants";
import { readOrderDraft } from "@/lib/checkout/draft";
import { buildWhatsAppHref } from "@/data/contact";
import { CheckoutProgress } from "@/components/checkout/CheckoutProgress";
import { ReviewOrderStep } from "@/components/checkout/ReviewOrderStep";
import { DetailsStep } from "@/components/checkout/DetailsStep";
import { DeliveryStep } from "@/components/checkout/DeliveryStep";
import { OrderSummaryCard } from "@/components/checkout/OrderSummaryCard";
import heroStyles from "@/components/marketing/HeroBase.module.css";
import styles from "./Checkout.module.css";
import clsx from "clsx";
import {
  trackCheckoutStepCompleted,
  trackCheckoutValidationFailed,
  trackPaymentFailed,
  trackPaymentInitiated,
} from "@/lib/analytics";

type CheckoutFormProps = {
  schoolSlug: string;
  schoolName: string;
  grade: string;
  gradeSlug: string;
  price: number;
  contents: string[];
  deliveryNote: string;
  draftId?: string;
};

type CheckoutStep = "review" | "details" | "delivery" | "pay";
type FulfilmentOption = "School collection" | "Delivery" | "Collection point";
type ContactMethod = "whatsapp" | "phone" | "email";

const STEPS: { id: CheckoutStep; label: string; title: string }[] = [
  { id: "review", label: "Review", title: "Review Order" },
  { id: "details", label: "Details", title: "Customer Details" },
  { id: "delivery", label: "Delivery", title: "Delivery or Collection" },
  { id: "pay", label: "Pay", title: "Confirm & Pay" },
];

function isValidEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function normalisePhone(value: string) {
  const trimmed = value.trim();
  if (trimmed.startsWith("+")) {
    return `+${trimmed.slice(1).replace(/\D/g, "")}`;
  }
  const digits = trimmed.replace(/\D/g, "");
  if (digits.startsWith("0027") && digits.length >= 13) {
    return `+27${digits.slice(4)}`;
  }
  return digits;
}

function isLikelySaPhone(value: string) {
  const normalised = normalisePhone(value);
  const digits = normalised.replace(/\D/g, "");
  return (
    (digits.startsWith("0") && digits.length === 10) ||
    (digits.startsWith("27") && digits.length === 11) ||
    (digits.startsWith("0027") && digits.length === 13)
  );
}

export function CheckoutForm({
  schoolSlug,
  schoolName,
  grade,
  gradeSlug,
  price: defaultPrice,
  contents,
  deliveryNote,
  draftId,
}: CheckoutFormProps) {
  const headingRef = useRef<HTMLHeadingElement>(null);
  const router = useRouter();
  const openTray = usePackTrayStore((s) => s.openTray);
  const handleBackToOrder = () => {
    openTray();
    router.back();
  };
  const [isSticky, setIsSticky] = useState(false);
  const [summaryOpen, setSummaryOpen] = useState(false);
  const lastScrollY = useRef(0);

  useEffect(() => {
    if (window.matchMedia("(max-width: 1024px)").matches) {
      setSummaryOpen(true);
    }
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;

      if (currentScrollY < 96) {
        setIsSticky(false);
      } else if (currentScrollY > lastScrollY.current + 4) {
        setIsSticky(true);
      } else if (currentScrollY < lastScrollY.current - 4) {
        setIsSticky(false);
      } else {
        lastScrollY.current = currentScrollY;
        return;
      }

      lastScrollY.current = currentScrollY;
    };

    lastScrollY.current = window.scrollY;
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const [draftLoaded, setDraftLoaded] = useState(false);
  const [draftTotal, setDraftTotal] = useState<number | null>(null);

  const [activeStep, setActiveStep] = useState(0);
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [buyerPhone, setBuyerPhone] = useState("");
  const [buyerEmail, setBuyerEmail] = useState("");
  const [preferredContactMethod, setPreferredContactMethod] =
    useState<ContactMethod>("whatsapp");
  const [learnerName, setLearnerName] = useState("");
  const [learnerNotes, setLearnerNotes] = useState("");
  const [consent, setConsent] = useState(false);

  const [hasPexcover, setHasPexcover] = useState(false);
  const [pexcoverName, setPexcoverName] = useState("");
  const [pexcoverSubjects, setPexcoverSubjects] = useState("");
  const [pexcoverLabelFormat, setPexcoverLabelFormat] =
    useState("First Name + Surname");
  const [pexcoverNotes, setPexcoverNotes] = useState("");

  const [fulfilmentOption, setFulfilmentOption] =
    useState<FulfilmentOption>("School collection");
  const [address, setAddress] = useState("");
  const [suburb, setSuburb] = useState("");
  const [city, setCity] = useState("");
  const [province, setProvince] = useState("");
  const [postalCode, setPostalCode] = useState("");
  const [deliveryNotes, setDeliveryNotes] = useState("");

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitting, setSubmitting] = useState(false);
  const idempotencyKeyRef = useRef<string | null>(null);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [orderSubmitted, setOrderSubmitted] = useState(false);
  const [orderReference, setOrderReference] = useState<string | null>(null);

  useEffect(() => {
    if (!draftId || draftLoaded) return;
    const draft = readOrderDraft(draftId);
    if (!draft) return;

    if (draft.estimatedTotal != null) {
      setDraftTotal(draft.estimatedTotal);
    }
    if (draft.pexcoverRequested) {
      setHasPexcover(true);
    }
    if (draft.pexcoverName) {
      setPexcoverName(draft.pexcoverName);
    }
    setDraftLoaded(true);
  }, [draftId, draftLoaded]);

  const packPrice = draftTotal ?? defaultPrice;
  const totalToPay = packPrice + (hasPexcover ? PEXCOVER_PRICE : 0);
  const currentStep = STEPS[activeStep] ?? STEPS[0];
  const itemCount = contents.length;
  const whatsAppHref = useMemo(
    () =>
      buildWhatsAppHref(
        `Hi Pexpacks, I need help with checkout for ${schoolName} ${grade}.`
      ),
    [grade, schoolName]
  );

  const deliveryAddressSummary = useMemo(() => {
    return [address, suburb, city, province, postalCode]
      .filter(Boolean)
      .join(", ");
  }, [address, suburb, city, province, postalCode]);

  function focusStepHeading() {
    window.requestAnimationFrame(() => headingRef.current?.focus());
  }

  function focusFirstInvalid(nextErrors: Record<string, string>) {
    const first = Object.keys(nextErrors)[0];
    if (!first) return;
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        const target = document.querySelector<HTMLElement>(
          `[data-field="${first}"], #${first}`
        );
        target?.scrollIntoView({ behavior: "smooth", block: "center" });
        target?.focus({ preventScroll: true });
      });
    });
  }

  function goToStep(index: number, options?: { preserveErrors?: boolean }) {
    const safeIndex = Math.max(0, Math.min(index, STEPS.length - 1));
    if (!options?.preserveErrors) {
      setErrors({});
    }
    setSubmitError(null);
    setActiveStep(safeIndex);
    focusStepHeading();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function clearFieldError(field: string) {
    setErrors((prev) => {
      if (!prev[field]) return prev;
      const next = { ...prev };
      delete next[field];
      return next;
    });
  }

  function getStepErrors(step: number): Record<string, string> {
    const nextErrors: Record<string, string> = {};

    if (step === 1) {
      if (!firstName.trim() || firstName.trim().length < 2)
        nextErrors.firstName = "Please enter your first name.";
      if (!lastName.trim() || lastName.trim().length < 2)
        nextErrors.lastName = "Please enter your surname.";
      if (!buyerPhone.trim())
        nextErrors.buyerPhone = "Please enter your phone number.";
      else if (!isLikelySaPhone(buyerPhone))
        nextErrors.buyerPhone =
          "Please enter a valid South African phone number.";
      if (!buyerEmail.trim())
        nextErrors.buyerEmail = "Please enter your email address.";
      else if (!isValidEmail(buyerEmail.trim()))
        nextErrors.buyerEmail = "Please enter a valid email address.";
      if (!learnerName.trim() || learnerName.trim().length < 2)
        nextErrors.learnerName = "Please enter the learner name.";
    }

    if (step === 2) {
      if (fulfilmentOption === "Delivery") {
        if (!address.trim()) nextErrors.address = "Please enter the delivery address.";
        if (!suburb.trim()) nextErrors.suburb = "Please enter the suburb.";
        if (!city.trim()) nextErrors.city = "Please enter the city.";
        if (!province.trim()) nextErrors.province = "Please enter the province.";
      }
      if (!consent)
        nextErrors.consent = "Please accept the order processing consent.";
    }

    return nextErrors;
  }

  function validateStep(step: number): boolean {
    const nextErrors = getStepErrors(step);

    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) {
      trackCheckoutValidationFailed({
        checkoutMode: "single-pack",
        step: STEPS[step]?.id || "unknown",
        fields: Object.keys(nextErrors),
      });
      focusFirstInvalid(nextErrors);
      return false;
    }
    return true;
  }

  function handleNext() {
    if (validateStep(activeStep)) {
      trackCheckoutStepCompleted({
        checkoutMode: "single-pack",
        step: currentStep.id,
      });
      goToStep(activeStep + 1);
    }
  }

  async function handlePay() {
    const detailsErrors = getStepErrors(1);
    if (Object.keys(detailsErrors).length > 0) {
      trackCheckoutValidationFailed({
        checkoutMode: "single-pack",
        step: "details",
        fields: Object.keys(detailsErrors),
      });
      setErrors(detailsErrors);
      goToStep(1, { preserveErrors: true });
      focusFirstInvalid(detailsErrors);
      return;
    }

    const deliveryErrors = getStepErrors(2);
    if (Object.keys(deliveryErrors).length > 0) {
      trackCheckoutValidationFailed({
        checkoutMode: "single-pack",
        step: "delivery",
        fields: Object.keys(deliveryErrors),
      });
      setErrors(deliveryErrors);
      goToStep(2, { preserveErrors: true });
      focusFirstInvalid(deliveryErrors);
      return;
    }

    setSubmitError(null);
    setSubmitting(true);

    const fulfilmentNotes = [
      deliveryNotes.trim() ? `Notes: ${deliveryNotes.trim()}` : "",
      learnerNotes.trim() ? `Learner notes: ${learnerNotes.trim()}` : "",
      fulfilmentOption === "Delivery"
        ? `Address: ${deliveryAddressSummary}`
        : "",
      preferredContactMethod
        ? `Preferred contact: ${preferredContactMethod}`
        : "",
      deliveryNote ? `Pack note: ${deliveryNote}` : "",
    ]
      .filter(Boolean)
      .join(" | ");

    try {
      if (!idempotencyKeyRef.current) {
        idempotencyKeyRef.current = crypto.randomUUID();
      }

      const response = await fetch("/api/ozow/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          orderId: idempotencyKeyRef.current,
          amount: totalToPay,
          customerEmail: buyerEmail.trim().toLowerCase(),
          buyerName: `${firstName.trim()} ${lastName.trim()}`.trim(),
          buyerEmail: buyerEmail.trim().toLowerCase(),
          buyerPhone: normalisePhone(buyerPhone),
          learnerName: learnerName.trim(),
          schoolSlug,
          schoolName,
          grade,
          gradeSlug,
          packType: "full",
          items: contents,
          estimatedTotal: totalToPay,
          deliveryMethod:
            fulfilmentOption === "School collection"
              ? "school_collection"
              : fulfilmentOption === "Delivery"
                ? "delivery"
                : "collection_point",
          notes: fulfilmentNotes || undefined,
          pexcoverSelected: hasPexcover,
          pexcoverAmount: hasPexcover ? PEXCOVER_PRICE : 0,
          pexcoverName: pexcoverName.trim() || undefined,
          pexcoverSubjects: pexcoverSubjects.trim() || undefined,
          pexcoverLabelFormat: pexcoverLabelFormat.trim() || undefined,
          pexcoverNotes: pexcoverNotes.trim() || undefined,
          idempotencyKey: idempotencyKeyRef.current,
        }),
      });

      const data = await response.json();

      if (!response.ok || !data.url) {
        console.error("Ozow Checkout Error Response:", response.status, data);
        trackPaymentFailed({
          checkoutMode: "single-pack",
          failureType: response.ok ? "invalid_response" : "api",
          statusCode: response.status,
        });
        const errorMessage =
          data.error ||
          data.message ||
          (data.errors && typeof data.errors === "object"
            ? Object.values(data.errors).join(". ")
            : "Failed to initialize Ozow payment.");
        setSubmitError(errorMessage);
        return;
      }

      trackPaymentInitiated({
        orderId: idempotencyKeyRef.current,
        totalPrice: totalToPay,
      });
      window.location.href = data.url;
      return;
    } catch (error) {
      console.error("Ozow Checkout Exception:", error);
      trackPaymentFailed({
        checkoutMode: "single-pack",
        failureType: "network",
      });
      setSubmitError(
        error instanceof Error
          ? error.message
          : "Failed to initialize Ozow payment."
      );
    } finally {
      setSubmitting(false);
    }
  }

  function renderStepContent() {
    switch (activeStep) {
      case 0:
        return (
          <ReviewOrderStep
            schoolSlug={schoolSlug}
            schoolName={schoolName}
            grade={grade}
            gradeSlug={gradeSlug}
            packPrice={packPrice}
            contents={contents}
            hasPexcover={hasPexcover}
            onPexcoverToggle={setHasPexcover}
            pexcoverName={pexcoverName}
            onPexcoverNameChange={setPexcoverName}
            pexcoverSubjects={pexcoverSubjects}
            onPexcoverSubjectsChange={setPexcoverSubjects}
            pexcoverLabelFormat={pexcoverLabelFormat}
            onPexcoverLabelFormatChange={setPexcoverLabelFormat}
            pexcoverNotes={pexcoverNotes}
            onPexcoverNotesChange={setPexcoverNotes}
            pexcoverPrice={PEXCOVER_PRICE}
          />
        );
      case 1:
        return (
          <DetailsStep
            firstName={firstName}
            onFirstNameChange={setFirstName}
            lastName={lastName}
            onLastNameChange={setLastName}
            buyerPhone={buyerPhone}
            onBuyerPhoneChange={setBuyerPhone}
            buyerEmail={buyerEmail}
            onBuyerEmailChange={setBuyerEmail}
            learnerName={learnerName}
            onLearnerNameChange={setLearnerName}
            schoolName={schoolName}
            grade={grade}
            learnerNotes={learnerNotes}
            onLearnerNotesChange={setLearnerNotes}
            preferredContactMethod={preferredContactMethod}
            onPreferredContactMethodChange={setPreferredContactMethod}
            errors={errors}
            onClearError={clearFieldError}
          />
        );
      case 2:
        return (
          <DeliveryStep
            fulfilmentOption={fulfilmentOption}
            onFulfilmentOptionChange={setFulfilmentOption}
            address={address}
            onAddressChange={setAddress}
            suburb={suburb}
            onSuburbChange={setSuburb}
            city={city}
            onCityChange={setCity}
            province={province}
            onProvinceChange={setProvince}
            postalCode={postalCode}
            onPostalCodeChange={setPostalCode}
            deliveryNotes={deliveryNotes}
            onDeliveryNotesChange={setDeliveryNotes}
            consent={consent}
            onConsentChange={setConsent}
            errors={errors}
            onClearError={clearFieldError}
          />
        );
      case 3:
        return (
          <div className={styles.confirmGrid}>
            <section className={styles.reviewBlock}>
              <div className={styles.reviewBlockContent}>
                <p className={styles.reviewBlockTitle}>Order Summary</p>
                <strong>{schoolName} - {grade}</strong>
                <span>{itemCount} items{hasPexcover ? " + Pexcover" : ""}</span>
              </div>
            </section>

            <section className={styles.reviewBlock}>
              <div className={styles.reviewBlockContent}>
                <p className={styles.reviewBlockTitle}>Customer</p>
                <strong>{`${firstName.trim()} ${lastName.trim()}`.trim() || "Name required"}</strong>
                <span>{buyerPhone || "Phone required"} - {buyerEmail || "Email required"}</span>
              </div>
            </section>

            <section className={styles.reviewBlock}>
              <div className={styles.reviewBlockContent}>
                <p className={styles.reviewBlockTitle}>Delivery / Collection</p>
                <strong>{fulfilmentOption}</strong>
                <span>
                  {fulfilmentOption === "Delivery"
                    ? deliveryAddressSummary || "Address required"
                    : "Pexpacks will confirm the handover details."}
                </span>
              </div>
            </section>

            <section className={styles.paymentReadyCard}>
              <div className={styles.paymentSecurityHeader}>
                <svg className={styles.securityLockIcon} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                  <path d="M7 11V7a5 5 0 0 1 10 0v4" />
                </svg>
                <div>
                  <p className={styles.confirmKicker}>Confirm Your Order</p>
                  <h3>Review and confirm</h3>
                </div>
              </div>
              <p className={styles.paymentSubtext}>
                You will be redirected to Ozow to pay the pack total securely.
                {fulfilmentOption === "Delivery"
                  ? " The home-delivery fee is not included and will be confirmed with you separately before dispatch."
                  : ""}
              </p>
            </section>

            {submitError ? (
              <p className={styles.formStatusError} role="alert">
                {submitError}
              </p>
            ) : null}
          </div>
        );
      default:
        return null;
    }
  }

  if (orderSubmitted && orderReference) {
    return (
      <div className={styles.checkoutShell}>
        <div className={styles.emptyCheckout}>
          <p className={styles.checkoutKicker}>Order Confirmed</p>
          <h1>Thank you for your order!</h1>
          <p>Your order reference is <strong>{orderReference}</strong>.</p>
          <p>We will be in touch shortly with payment and delivery details.</p>
          <Button href="/schools" variant="primary" size="lg">
            Browse more packs
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.checkoutShell}>
      <div className={styles.checkoutHeader}>
        {activeStep > 0 ? (
          <div>
            <Button
              type="button"
              variant="secondary"
              className={clsx(styles.desktopOnly, "rounded-full")}
              onClick={handleBackToOrder}
            >
              Back to Order
            </Button>
            <Button
              type="button"
              variant="secondary"
              className={clsx(styles.mobileOnly, "rounded-full")}
              onClick={() => goToStep(activeStep - 1)}
            >
              Back
            </Button>
          </div>
        ) : (
          <Button
            type="button"
            variant="secondary"
            className="rounded-full"
            onClick={handleBackToOrder}
          >
            Back to Order
          </Button>
        )}
        <div
          className={clsx(styles.stickyHeaderButton, isSticky && styles.isSticky)}
        >
          <Button
            variant="white"
            size="lg"
            iconDirection="none"
            className={styles.stickyCtaBtn}
            onClick={() => setSummaryOpen(!summaryOpen)}
            aria-expanded={summaryOpen}
            aria-controls="checkout-order-summary"
          >
            <span className={styles.stickyCtaLabel}>
              {fulfilmentOption === "Delivery" ? "Pack total" : "Total to pay"}
            </span>
            <span className={styles.stickyCtaPrice}>
              {formatCurrency(totalToPay)}
            </span>
          </Button>
        </div>
        <a
          href={whatsAppHref}
          target="_blank"
          rel="noopener noreferrer"
          className={styles.helpLink}
        >
          Need Help?
        </a>
      </div>

      <div className={styles.checkoutGrid}>
        <div className={styles.mainColumn}>
          <CheckoutProgress steps={STEPS} activeStep={activeStep} />

          <section className={styles.stepCard} aria-labelledby="checkout-step-heading">
            <div className={styles.stepIntro}>
              <p className={clsx(heroStyles.eyebrow, styles.stepEyebrow)}>
                Secure checkout
              </p>
              <h1
                id="checkout-step-heading"
                ref={headingRef}
                tabIndex={-1}
              >
                {currentStep.title}
              </h1>
              <p>
                {activeStep === 0
                  ? "Make sure you check your pack details before continuing to the next step. You can change the school and grade below."
                  : null}
                {activeStep === 1
                  ? "We will use these details to confirm your order and send updates."
                  : null}
                {activeStep === 2
                  ? "Choose how you want to receive your pack."
                  : null}
                {activeStep === 3
                  ? "Review everything before confirming your order."
                  : null}
              </p>
            </div>

            {renderStepContent()}
          </section>

          <div className={styles.formActions}>
            <Button
              type="button"
              variant="outline"
              iconDirection="left"
              onClick={() => goToStep(activeStep - 1)}
              disabled={activeStep === 0}
            >
              Back
            </Button>
            {activeStep < 3 ? (
              <Button type="button" variant="primary" onClick={handleNext}>
                {activeStep === 2
                  ? "Review and pay"
                  : activeStep === 0
                    ? "Continue to details"
                    : "Continue to delivery"}
              </Button>
            ) : (
              <Button
                type="button"
                variant="primary"
                onClick={handlePay}
                disabled={submitting}
                aria-busy={submitting}
              >
                {submitting
                  ? "Preparing secure checkout..."
                  : fulfilmentOption === "Delivery"
                    ? `Pay Pack Total ${formatCurrency(totalToPay)}`
                    : `Pay Securely ${formatCurrency(totalToPay)}`}
              </Button>
            )}
          </div>

          <OrderSummaryCard
            schoolName={schoolName}
            gradeName={grade}
            packPrice={packPrice}
            itemCount={contents.length}
            totalToPay={totalToPay}
            fulfilmentOption={fulfilmentOption}
            hasPexcover={hasPexcover}
            summaryOpen={summaryOpen}
            whatsAppHref={whatsAppHref}
            deliveryFeePending={fulfilmentOption === "Delivery"}
          />
        </div>
      </div>

      <div className={styles.mobileStickyCta}>
        {activeStep < 3 ? (
          <Button
            type="button"
            variant="primary"
            className={styles.fullWidth}
            onClick={handleNext}
          >
            {activeStep === 2
              ? "Review and pay"
              : activeStep === 0
                ? "Continue to details"
                : "Continue to delivery"}
          </Button>
        ) : (
          <Button
            type="button"
            variant="primary"
            className={styles.fullWidth}
            onClick={handlePay}
            disabled={submitting}
          >
            {submitting
              ? "Preparing secure checkout..."
              : fulfilmentOption === "Delivery"
                ? `Pay Pack Total ${formatCurrency(totalToPay)}`
                : `Pay Securely ${formatCurrency(totalToPay)}`}
          </Button>
        )}
      </div>
    </div>
  );
}

'use client'

import { useRouter } from 'next/navigation'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { usePackTrayStore } from '@/store/usePackTrayStore'
import type { TrayPackItem } from '@/store/usePackTrayStore'
import { calculateTrayTotal } from '@/lib/order/calculateTrayTotal'
import { formatCurrency } from '@/lib/formatCurrency'
import { PEXCOVER_PRICE } from '@/lib/constants'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import Textarea from '@/components/ui/Textarea'
import { buildWhatsAppHref } from '@/data/contact'
import clsx from 'clsx'
import {
  trackCheckoutValidationFailed,
  trackPaymentFailed,
  trackPaymentInitiated,
} from '@/lib/analytics'
import styles from '@/app/checkout/Checkout.module.css'

type FulfilmentOption =
  | 'school_collection'
  | 'home_delivery'
  | 'arranged_collection'
type ContactMethod = 'whatsapp' | 'phone' | 'email'
type CheckoutSummarySection = 'details' | 'delivery'

const contactOptions: { value: ContactMethod; label: string }[] = [
  { value: 'whatsapp', label: 'WhatsApp' },
  { value: 'phone', label: 'Phone call' },
  { value: 'email', label: 'Email' },
]

const fulfilmentOptions: {
  value: FulfilmentOption
  title: string
  description: string
  note: string
}[] = [
  {
    value: 'school_collection',
    title: 'School collection',
    description: 'Please pick up your stationery pack from the school or the designated handover point.',
    note: 'Included',
  },
  {
    value: 'home_delivery',
    title: 'Home delivery',
    description:
      'Home delivery will incur additional charges, which will be confirmed separately.',
    note: 'Address required',
  },
  {
    value: 'arranged_collection',
    title: 'Arranged collection',
    description: 'You can choose your own delivery location. We will contact you to confirm your preferred option.',
    note: 'We will confirm',
  },
]

function isValidEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
}

function normalisePhone(value: string) {
  const trimmed = value.trim()
  if (trimmed.startsWith('+')) {
    return `+${trimmed.slice(1).replace(/\D/g, '')}`
  }
  const digits = trimmed.replace(/\D/g, '')
  if (digits.startsWith('0027') && digits.length >= 13) {
    return `+27${digits.slice(4)}`
  }
  return digits
}

function isLikelySaPhone(value: string) {
  const normalised = normalisePhone(value)
  const digits = normalised.replace(/\D/g, '')
  return (
    (digits.startsWith('0') && digits.length === 10) ||
    (digits.startsWith('27') && digits.length === 11) ||
    (digits.startsWith('0027') && digits.length === 13)
  )
}

function fulfilmentToApiMethod(option: FulfilmentOption) {
  if (option === 'school_collection') return 'school_collection'
  if (option === 'home_delivery') return 'delivery'
  return 'collection_point'
}

function getPackTotal(pack: TrayPackItem) {
  return pack.totalPrice + (pack.wantsPexcover ? PEXCOVER_PRICE : 0)
}

function getItemLineTotal(item: TrayPackItem['items'][number]) {
  return typeof item.unitPrice === 'number'
    ? item.unitPrice * item.quantity
    : null
}

function getPackItemPreview(pack: TrayPackItem) {
  return pack.items.slice(0, 4)
}

function FulfilmentIcon({ option }: { option: FulfilmentOption }) {
  if (option === 'school_collection') {
    return (
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d="M12 2 2 7l10 5 10-5-10-5ZM2 17l10 5 10-5M2 12l10 5 10-5" />
      </svg>
    )
  }

  if (option === 'home_delivery') {
    return (
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <rect x="1" y="3" width="15" height="13" rx="2" />
        <path d="M16 8h4l3 3v5h-7V8Z" />
        <circle cx="5.5" cy="18.5" r="2.5" />
        <circle cx="18.5" cy="18.5" r="2.5" />
      </svg>
    )
  }

  return (
    <svg viewBox="0 0 24 24" aria-hidden="true">
      <rect x="3" y="5" width="18" height="14" rx="2" />
      <path d="M3 10h18M7 15h4" />
    </svg>
  )
}

export function TrayCheckoutClient() {
  const router = useRouter()
  const packs = usePackTrayStore((s) => s.packs)
  const openTray = usePackTrayStore((s) => s.openTray)
  const updatePackDetails = usePackTrayStore((s) => s.updatePackDetails)

  const [expandedPacks, setExpandedPacks] = useState<Record<string, boolean>>(
    {},
  )
  const [editNameIndex, setEditNameIndex] = useState<number | null>(null)
  const [learnerInputs, setLearnerInputs] = useState<string[]>(() =>
    packs.map((p) => p.learnerName || ''),
  )

  const [fullName, setFullName] = useState('')
  const [buyerPhone, setBuyerPhone] = useState('')
  const [buyerEmail, setBuyerEmail] = useState('')
  const [preferredContactMethod, setPreferredContactMethod] =
    useState<ContactMethod>('whatsapp')
  const [consent, setConsent] = useState(false)

  const [fulfilmentOption, setFulfilmentOption] =
    useState<FulfilmentOption>('school_collection')
  const [multiSchoolDrop, setMultiSchoolDrop] = useState<string | null>(null)
  const [address, setAddress] = useState('')
  const [suburb, setSuburb] = useState('')
  const [city, setCity] = useState('')
  const [province, setProvince] = useState('')
  const [postalCode, setPostalCode] = useState('')
  const [deliveryNotes, setDeliveryNotes] = useState('')

  const [errors, setErrors] = useState<Record<string, string>>({})
  const [submitting, setSubmitting] = useState(false)
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [orderSubmitted, setOrderSubmitted] = useState(false)
  const [orderReference, setOrderReference] = useState<string | null>(null)
  const idempotencyKeyRef = useRef<string | null>(null)

  const [mobileSectionSummaryOpen, setMobileSectionSummaryOpen] = useState<
    Record<CheckoutSummarySection, boolean>
  >({
    details: true,
    delivery: true,
  })
  const fieldRefs = useRef<
    Record<string, HTMLInputElement | HTMLTextAreaElement | null>
  >({})
  const sectionRefs = useRef<
    Record<CheckoutSummarySection, HTMLElement | null>
  >({
    details: null,
    delivery: null,
  })
  const consentRef = useRef<HTMLElement | null>(null)
  const summaryRef = useRef<HTMLElement | null>(null)

  const total = useMemo(() => calculateTrayTotal(packs), [packs])

  const pexcoverCount = useMemo(
    () => packs.filter((p) => p.wantsPexcover).length,
    [packs],
  )
  const pexcoverTotal = pexcoverCount * PEXCOVER_PRICE
  const itemsTotal = total - pexcoverTotal

  const uniqueSchools = useMemo(() => {
    const map = new Map<string, { name: string; slug: string }>()
    packs.forEach((p) => {
      if (p.schoolSlug && p.schoolName && !map.has(p.schoolSlug)) {
        map.set(p.schoolSlug, { name: p.schoolName, slug: p.schoolSlug })
      }
    })
    return Array.from(map.values())
  }, [packs])

  const isSingleSchool = uniqueSchools.length <= 1
  const deliveryExpanded = fulfilmentOption === 'home_delivery'
  const canSubmit = packs.length > 0 && total > 0 && !submitting
  const detailsSectionHasErrors = Boolean(
    errors.fullName ||
    errors.buyerPhone ||
    errors.buyerEmail ||
    Object.keys(errors).some((key) => key.startsWith('learner_')),
  )
  const showDetailsHiddenWarning =
    detailsSectionHasErrors && !mobileSectionSummaryOpen.details

  const toggleMobileSectionSummary = useCallback(
    (section: CheckoutSummarySection) => {
      setMobileSectionSummaryOpen((current) => ({
        ...current,
        [section]: !current[section],
      }))
    },
    [],
  )

  useEffect(() => {
    setLearnerInputs((prev) => {
      if (prev.length === packs.length) return prev
      return packs.map((pack, index) => prev[index] ?? pack.learnerName ?? '')
    })
  }, [packs])

  useEffect(() => {
    if (isSingleSchool && fulfilmentOption === 'school_collection') {
      setMultiSchoolDrop(uniqueSchools[0]?.slug ?? null)
    }
  }, [fulfilmentOption, isSingleSchool, uniqueSchools])

  const deliveryAddressSummary = useMemo(() => {
    return [address, suburb, city, province, postalCode]
      .filter(Boolean)
      .join(', ')
  }, [address, suburb, city, province, postalCode])

  const handleLearnerNameChange = useCallback(
    (index: number, value: string) => {
      setLearnerInputs((prev) => {
        const next = [...prev]
        next[index] = value
        return next
      })
    },
    [],
  )

  const handleLearnerNameBlur = useCallback(
    (index: number) => {
      const pack = packs[index]
      if (!pack) return
      const name = learnerInputs[index]?.trim() || ''
      if (name !== (pack.learnerName || '')) {
        updatePackDetails(pack.id, name, pack.wantsPexcover || false)
      }
      setEditNameIndex(null)
    },
    [packs, learnerInputs, updatePackDetails],
  )

  const handleLearnerNameKeyDown = useCallback(
    (e: React.KeyboardEvent, index: number) => {
      if (e.key === 'Enter') {
        ;(e.target as HTMLInputElement).blur()
      }
      if (e.key === 'Escape') {
        setLearnerInputs((prev) => {
          const next = [...prev]
          next[index] = packs[index]?.learnerName || ''
          return next
        })
        setEditNameIndex(null)
      }
    },
    [packs],
  )

  const handleBackToOrder = useCallback(() => {
    openTray()
    router.back()
  }, [openTray, router])

  function clearFieldError(field: string) {
    setErrors((prev) => {
      if (!prev[field]) return prev
      const next = { ...prev }
      delete next[field]
      return next
    })
  }

  function getSectionForError(field: string): CheckoutSummarySection | null {
    if (
      field === 'fullName' ||
      field === 'buyerPhone' ||
      field === 'buyerEmail'
    ) {
      return 'details'
    }

    if (
      field === 'address' ||
      field === 'suburb' ||
      field === 'city' ||
      field === 'province' ||
      field === 'multiSchoolDrop'
    ) {
      return 'delivery'
    }

    return null
  }

  function guideToIncompleteField(field: string) {
    const section = getSectionForError(field)
    const learnerMatch = field.match(/^learner_(\d+)$/)

    if (section) {
      setMobileSectionSummaryOpen((current) => ({
        ...current,
        [section]: true,
      }))
    }

    if (learnerMatch) {
      setEditNameIndex(Number(learnerMatch[1]))
    }

    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        const fieldNode = fieldRefs.current[field]
        const target =
          fieldNode ||
          (learnerMatch ? summaryRef.current : null) ||
          (field === 'consent' ? consentRef.current : null) ||
          (section ? sectionRefs.current[section] : null)

        target?.scrollIntoView({ behavior: 'smooth', block: 'center' })

        if (fieldNode) {
          fieldNode.focus({ preventScroll: true })
        } else if (target instanceof HTMLElement) {
          target.focus({ preventScroll: true })
        }
      })
    })
  }

  function validate(): boolean {
    const nextErrors: Record<string, string> = {}

    if (packs.length === 0)
      nextErrors.packs = 'Choose a school pack before checkout.'
    if (total <= 0)
      nextErrors.total = 'Your order total must be greater than zero.'
    if (!fullName.trim() || fullName.trim().length < 2)
      nextErrors.fullName = 'Please enter your full name.'
    if (!buyerPhone.trim())
      nextErrors.buyerPhone = 'Please enter your phone number.'
    else if (!isLikelySaPhone(buyerPhone))
      nextErrors.buyerPhone = 'Please enter a valid South African phone number.'
    if (!buyerEmail.trim())
      nextErrors.buyerEmail = 'Please enter your email address.'
    else if (!isValidEmail(buyerEmail.trim()))
      nextErrors.buyerEmail = 'Please enter a valid email address.'

    for (let i = 0; i < packs.length; i++) {
      if (!learnerInputs[i]?.trim()) {
        nextErrors[`learner_${i}`] = `Please enter a name for learner ${i + 1}.`
      }
    }

    if (deliveryExpanded) {
      if (!address.trim())
        nextErrors.address = 'Please enter the delivery address.'
      if (!suburb.trim()) nextErrors.suburb = 'Please enter the suburb.'
      if (!city.trim()) nextErrors.city = 'Please enter the city.'
      if (!province.trim()) nextErrors.province = 'Please enter the province.'
    }

    if (
      fulfilmentOption === 'school_collection' &&
      uniqueSchools.length > 1 &&
      !multiSchoolDrop
    ) {
      nextErrors.multiSchoolDrop =
        'Select which school the box should be dropped at.'
    }
    if (!consent)
      nextErrors.consent = 'Please accept the order processing consent.'

    setErrors(nextErrors)

    const firstError = Object.keys(nextErrors)[0]
    if (firstError) {
      trackCheckoutValidationFailed({
        checkoutMode: 'tray',
        step: getSectionForError(firstError) || 'order',
        fields: Object.keys(nextErrors),
      })
      guideToIncompleteField(firstError)
    }

    return Object.keys(nextErrors).length === 0
  }

  async function handlePay() {
    if (submitting) return
    if (!validate()) return

    setSubmitError(null)
    setSubmitting(true)

    const notes = [
      deliveryNotes.trim() ? `Notes: ${deliveryNotes.trim()}` : '',
      deliveryExpanded ? `Address: ${deliveryAddressSummary}` : '',
      preferredContactMethod
        ? `Preferred contact: ${preferredContactMethod}`
        : '',
    ]
      .filter(Boolean)
      .join(' | ')

    try {
      if (!idempotencyKeyRef.current) {
        idempotencyKeyRef.current = crypto.randomUUID()
      }

      const response = await fetch('/api/ozow/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          orderId: idempotencyKeyRef.current,
          amount: total,
          customerEmail: buyerEmail.trim().toLowerCase(),
          buyerName: fullName.trim(),
          buyerEmail: buyerEmail.trim().toLowerCase(),
          buyerPhone: normalisePhone(buyerPhone),
          packs: packs.map((pack, pi) => ({
            learnerName:
              learnerInputs[pi]?.trim() || pack.learnerName?.trim() || '',
            schoolSlug: pack.schoolSlug || '',
            schoolName: pack.schoolName || '',
            grade: pack.grade || '',
            gradeSlug: pack.gradeSlug || '',
            packName: pack.packName,
            packMode: pack.packMode,
            items: pack.items.map((i) => ({
              name: i.name,
              quantity: i.quantity,
              unitPrice: i.unitPrice,
            })),
            totalPrice: pack.totalPrice,
            modifications: pack.modifications,
            wantsPexcover: pack.wantsPexcover || false,
            pexcoverPrice: pack.wantsPexcover ? PEXCOVER_PRICE : 0,
            basePackPrice: pack.totalPrice,
          })),
          isTrayOrder: true,
          estimatedTotal: total,
          deliveryMethod: fulfilmentToApiMethod(fulfilmentOption),
          primarySchoolSlug:
            uniqueSchools.length > 1
              ? multiSchoolDrop
              : uniqueSchools[0]?.slug || packs[0]?.schoolSlug || '',
          notes: notes || undefined,
          idempotencyKey: idempotencyKeyRef.current,
        }),
      })

      const data = await response.json()

      if (!response.ok || !data.url) {
        console.error("Ozow Checkout Error Response:", response.status, data)
        trackPaymentFailed({
          checkoutMode: 'tray',
          failureType: response.ok ? 'invalid_response' : 'api',
          statusCode: response.status,
        })
        const errorMessage =
          data.error ||
          data.message ||
          (data.errors && typeof data.errors === 'object'
            ? Object.values(data.errors).join('. ')
            : 'Failed to initialize Ozow payment.')
        setSubmitError(errorMessage)
        return
      }

      if (idempotencyKeyRef.current) {
        trackPaymentInitiated({
          orderId: idempotencyKeyRef.current,
          totalPrice: total,
        })
      }
      window.location.href = data.url
      return
    } catch (error) {
      console.error("Ozow Checkout Exception:", error)
      trackPaymentFailed({
        checkoutMode: 'tray',
        failureType: 'network',
      })
      setSubmitError(
        error instanceof Error
          ? error.message
          : 'Failed to initialize Ozow payment.',
      )
    } finally {
      setSubmitting(false)
    }
  }

  if (orderSubmitted && orderReference) {
    return (
      <div className={styles.checkoutShell}>
        <div className={styles.emptyCheckout}>
          <p className={styles.checkoutKicker}>Order Confirmed</p>
          <h1>Thank you for your order!</h1>
          <p>Your order reference is <strong>{orderReference}</strong>.</p>
          <p>We will be in touch shortly with payment and delivery details.</p>
          <Button href="/schools" variant="primary" size="lg">
            Browse more packs
          </Button>
        </div>
      </div>
    )
  }

  if (packs.length === 0) {
    return (
      <div className={styles.checkoutShell}>
        <div className={styles.emptyCheckout}>
          <p className={styles.checkoutKicker}>Checkout</p>
          <h1>No packs in your order.</h1>
          <p>Choose a school pack before checkout.</p>
          <Button href="/schools" variant="primary" size="lg">
            Find a school pack
          </Button>
        </div>
      </div>
    )
  }

  return (
    <div className={styles.checkoutShell}>
      <header className={styles.checkoutHeader}>
        <button
          type="button"
          className={styles.backToOrder}
          onClick={handleBackToOrder}
        >
          Back to order
        </button>
        <a
          href={buildWhatsAppHref('Hi Pexpacks, I need help with checkout.')}
          target="_blank"
          rel="noopener noreferrer"
          className={styles.helpLink}
        >
          Need help?
        </a>
      </header>

      <div className={styles.checkoutGrid}>
        <section className={clsx(styles.stepCard, styles.checkoutHero)}>
          <p className={styles.checkoutKicker}>Checkout</p>
          <h1>Review your packs and confirm your order.</h1>
          <p>
            Add your details, choose delivery or collection, and submit your
            order. We will be in touch with payment details.
          </p>
        </section>

        <form
          className={styles.mainColumn}
          aria-label="Checkout details"
          onSubmit={(e) => e.preventDefault()}
        >
          <section
            ref={(node) => {
              sectionRefs.current.details = node
            }}
            tabIndex={-1}
            className={clsx(styles.checkoutSection, showDetailsHiddenWarning && styles.checkoutSectionWarning)}
            aria-labelledby="customer-details-heading"
          >
            <div className={styles.sectionHeader}>
              <span className={styles.sectionNumber}>1</span>
              <div>
                <h2 id="customer-details-heading">Your details</h2>
                <p>
                  We use these details for order updates and delivery or
                  collection support.
                </p>
              </div>
              <button
                type="button"
                className={styles.mobileSummaryToggle}
                onClick={() => toggleMobileSectionSummary('details')}
                aria-expanded={mobileSectionSummaryOpen.details}
                aria-controls="customer-details-summary"
              >
                {mobileSectionSummaryOpen.details
                  ? 'Hide Summary'
                  : 'View Summary'}
              </button>
            </div>
            <div
              id="customer-details-summary"
              className={clsx(styles.mobileCollapsibleSummary, mobileSectionSummaryOpen.details && styles.mobileCollapsibleSummaryOpen)}
            >
              <div className={styles.formGrid}>
                <Input
                  id="fullName"
                  ref={(node) => {
                    fieldRefs.current.fullName = node
                  }}
                  label="Full name"
                  helper="We use this to confirm your order and payment updates."
                  type="text"
                  value={fullName}
                  onChange={(e) => {
                    setFullName(e.target.value)
                    clearFieldError('fullName')
                  }}
                  placeholder="e.g. Sarah Dlamini"
                  error={errors.fullName}
                  autoComplete="name"
                />
                <Input
                  id="buyerPhone"
                  ref={(node) => {
                    fieldRefs.current.buyerPhone = node
                  }}
                  label="Phone number"
                  helper="WhatsApp or call is fastest for support."
                  type="tel"
                  value={buyerPhone}
                  onChange={(e) => {
                    setBuyerPhone(e.target.value)
                    clearFieldError('buyerPhone')
                  }}
                  placeholder="e.g. 078 003 6048"
                  error={errors.buyerPhone}
                  autoComplete="tel"
                />
                <Input
                  id="buyerEmail"
                  ref={(node) => {
                    fieldRefs.current.buyerEmail = node
                  }}
                  label="Email address"
                  helper="Used for order updates and payment confirmation."
                  type="email"
                  value={buyerEmail}
                  onChange={(e) => {
                    setBuyerEmail(e.target.value)
                    clearFieldError('buyerEmail')
                  }}
                  placeholder="name@example.com"
                  error={errors.buyerEmail}
                  autoComplete="email"
                />
                <fieldset className={styles.contactMethodGroup}>
                  <legend>Preferred contact method</legend>
                  <p>
                    Choose how we should reach you if the order needs a quick
                    check.
                  </p>
                  <div className={styles.segmentedOptions}>
                    {contactOptions.map((option) => (
                      <label
                        key={option.value}
                        className={clsx(styles.segmentedOption, preferredContactMethod === option.value && styles.segmentedOptionActive)}
                      >
                        <input
                          type="radio"
                          name="preferredContactMethod"
                          value={option.value}
                          checked={preferredContactMethod === option.value}
                          onChange={() =>
                            setPreferredContactMethod(option.value)
                          }
                        />
                        <span>{option.label}</span>
                      </label>
                    ))}
                  </div>
                </fieldset>
              </div>
              {packs.map((pack, index) => {
                const errKey = `learner_${index}`
                return errors[errKey] ? (
                  <p key={errKey} className={styles.fieldError}>
                    Learner {index + 1} ({pack.packName}): {errors[errKey]}
                  </p>
                ) : null
              })}
            </div>
            {showDetailsHiddenWarning ? (
              <p className={styles.mobileHiddenSummaryWarning} role="alert">
                Fill in your details (Click "View Summary")
              </p>
            ) : null}
          </section>

          <section
            ref={(node) => {
              sectionRefs.current.delivery = node
            }}
            tabIndex={-1}
            className={styles.checkoutSection}
            aria-labelledby="fulfilment-heading"
          >
            <div className={styles.sectionHeader}>
              <span className={styles.sectionNumber}>2</span>
              <div>
                <h2 id="fulfilment-heading">Delivery or collection</h2>
                <p>Choose how you want to receive this order.</p>
              </div>
              <button
                type="button"
                className={styles.mobileSummaryToggle}
                onClick={() => toggleMobileSectionSummary('delivery')}
                aria-expanded={mobileSectionSummaryOpen.delivery}
                aria-controls="fulfilment-summary"
              >
                {mobileSectionSummaryOpen.delivery
                  ? 'Hide Summary'
                  : 'View Summary'}
              </button>
            </div>

            <div
              id="fulfilment-summary"
              className={clsx(styles.mobileCollapsibleSummary, mobileSectionSummaryOpen.delivery && styles.mobileCollapsibleSummaryOpen)}
            >
              <fieldset className={styles.optionFieldset}>
                <legend className={styles.srOnly}>
                  Delivery or collection method
                </legend>
                <div className={styles.deliveryOptions}>
                  {fulfilmentOptions.map((option) => (
                    <label
                      key={option.value}
                      className={clsx(styles.deliveryOption, fulfilmentOption === option.value && styles.deliveryOptionSelected)}
                    >
                      <input
                        type="radio"
                        name="fulfilment"
                        value={option.value}
                        checked={fulfilmentOption === option.value}
                        onChange={() => {
                          setFulfilmentOption(option.value)
                          clearFieldError('multiSchoolDrop')
                        }}
                      />
                      <div className={styles.deliveryOptionHeader}>
                        <span className={styles.deliveryIcon}>
                          <FulfilmentIcon option={option.value} />
                        </span>
                        <strong>{option.title}</strong>
                      </div>
                      <p className={styles.deliveryDescription}>
                        {option.description}
                      </p>
                      <span className={styles.deliveryBadge}>
                        {option.note}
                      </span>
                    </label>
                  ))}
                </div>
              </fieldset>

              {fulfilmentOption === 'school_collection' &&
              uniqueSchools.length > 1 ? (
                <div className={styles.schoolDropoffGroup}>
                  <p className={styles.schoolDropoffLabel}>
                    Which school should the main box be dropped at?
                  </p>
                  <div className={styles.schoolDropoffRow}>
                    {uniqueSchools.map((school) => {
                      const isSelected = multiSchoolDrop === school.slug
                      return (
                        <label
                          key={school.slug}
                          className={clsx(styles.schoolDropoffCard, isSelected && styles.schoolDropoffCardActive)}
                        >
                          <input
                            type="radio"
                            name="multiSchoolDrop"
                            value={school.slug}
                            checked={isSelected}
                            onChange={() => {
                              setMultiSchoolDrop(school.slug)
                              clearFieldError('multiSchoolDrop')
                            }}
                            className={styles.schoolDropoffRadio}
                          />
                          <span className={styles.schoolDropoffText}>
                            {school.name}
                          </span>
                        </label>
                      )
                    })}
                  </div>
                  {errors.multiSchoolDrop ? (
                    <p className={styles.fieldError}>
                      {errors.multiSchoolDrop}
                    </p>
                  ) : null}
                </div>
              ) : null}

              {deliveryExpanded ? (
                <div className={styles.addressPanel}>
                  <Input
                    id="address"
                    ref={(node) => {
                      fieldRefs.current.address = node
                    }}
                    label="Address line"
                    type="text"
                    value={address}
                    onChange={(e) => {
                      setAddress(e.target.value)
                      clearFieldError('address')
                    }}
                    placeholder="e.g. 42 Main Road"
                    error={errors.address}
                    autoComplete="street-address"
                  />
                  <Input
                    id="suburb"
                    ref={(node) => {
                      fieldRefs.current.suburb = node
                    }}
                    label="Suburb"
                    type="text"
                    autoComplete="address-level2"
                    value={suburb}
                    onChange={(e) => {
                      setSuburb(e.target.value)
                      clearFieldError('suburb')
                    }}
                    placeholder="e.g. Gardens"
                    error={errors.suburb}
                  />
                  <Input
                    id="city"
                    ref={(node) => {
                      fieldRefs.current.city = node
                    }}
                    label="City"
                    type="text"
                    autoComplete="address-level2"
                    value={city}
                    onChange={(e) => {
                      setCity(e.target.value)
                      clearFieldError('city')
                    }}
                    placeholder="e.g. Cape Town"
                    error={errors.city}
                  />
                  <Input
                    id="province"
                    ref={(node) => {
                      fieldRefs.current.province = node
                    }}
                    label="Province"
                    type="text"
                    autoComplete="address-level1"
                    value={province}
                    onChange={(e) => {
                      setProvince(e.target.value)
                      clearFieldError('province')
                    }}
                    placeholder="e.g. Western Cape"
                    error={errors.province}
                  />
                  <Input
                    id="postalCode"
                    label="Postal code"
                    type="text"
                    value={postalCode}
                    onChange={(e) => setPostalCode(e.target.value)}
                    placeholder="e.g. 8001"
                    autoComplete="postal-code"
                  />
                </div>
              ) : null}

              <Textarea
                id="deliveryNotes"
                label="Delivery notes (optional)"
                helper="Add gate codes, collection notes, or anything the Pexpacks team should know."
                value={deliveryNotes}
                onChange={(e) => setDeliveryNotes(e.target.value)}
                rows={4}
                className={styles.deliveryNotesField}
              />
            </div>
          </section>

          <section
            ref={consentRef}
            tabIndex={-1}
            className={styles.consentCard}
            aria-label="Consent"
          >
            <label className={styles.consentField}>
              <input
                ref={(node) => {
                  fieldRefs.current.consent = node
                }}
                type="checkbox"
                id="consent"
                checked={consent}
                onChange={(e) => {
                  setConsent(e.target.checked)
                  clearFieldError('consent')
                }}
                aria-invalid={!!errors.consent}
              />
              <span>
                I agree that Pexpacks may process my personal information to
                complete this order, send order updates, and contact
                me about delivery or collection. I have read and agree to the{' '}
                <a href="/privacy-policy" target="_blank">
                  privacy policy
                </a>
                ,{' '}
                <a href="/terms" target="_blank">
                  terms of use
                </a>
                ,{' '}
                <a href="/delivery-policy" target="_blank">
                  delivery policy
                </a>
                ,{' '}
                <a href="/happy-pay-terms" target="_blank">
                  happy pay terms
                </a>
                , and{' '}
                <a href="/returns-refunds-policy" target="_blank">
                  returns &amp; refunds policy
                </a>
                .
              </span>
            </label>
            {errors.consent ? (
              <p className={styles.fieldError}>{errors.consent}</p>
            ) : null}
          </section>

          {submitError ? (
            <p className={styles.formStatusError} role="alert">
              {submitError}
            </p>
          ) : null}
        </form>

        <aside
          ref={summaryRef}
          tabIndex={-1}
          className={styles.summaryColumn}
          aria-labelledby="order-summary-heading"
        >
          <div className={styles.summaryCard}>
            <div className={styles.summaryHeader}>
              <div>
                <p className={styles.checkoutKicker}>Your order</p>
                <h2 id="order-summary-heading">Order summary</h2>
              </div>
              <span>
                {packs.length} {packs.length === 1 ? 'pack' : 'packs'}
              </span>
            </div>

            <div className={styles.orderSummaryList}>
              {packs.map((pack, index) => {
                const isExpanded = !!expandedPacks[pack.id]
                const previewItems = getPackItemPreview(pack)
                const hiddenCount = Math.max(
                  pack.items.length - previewItems.length,
                  0,
                )
                const learnerName = learnerInputs[index]?.trim()
                const learnerLabel = learnerName
                  ? `Learner ${index + 1}: ${learnerName}`
                  : `Learner ${index + 1}: Add learner name`
                return (
                  <article key={pack.id} className={styles.orderPackCard}>
                    <div className={styles.orderPackTop}>
                      <div>
                        {editNameIndex === index ? (
                          <Input
                            ref={(node) => {
                              fieldRefs.current[`learner_${index}`] = node
                            }}
                            type="text"
                            value={learnerInputs[index] || ''}
                            onChange={(e) =>
                              handleLearnerNameChange(index, e.target.value)
                            }
                            onBlur={() => handleLearnerNameBlur(index)}
                            onKeyDown={(e) =>
                              handleLearnerNameKeyDown(e, index)
                            }
                            placeholder="Learner name"
                            aria-label={`Learner ${index + 1} name`}
                            autoFocus
                          />
                        ) : (
                          <button
                            type="button"
                            className={clsx(styles.orderPackLearnerLabel, errors[`learner_${index}`] && styles.orderPackLearnerLabelError)}
                            onClick={() => setEditNameIndex(index)}
                            aria-label={`Edit learner ${index + 1} name`}
                          >
                            {learnerLabel}
                          </button>
                        )}
                      </div>
                      <strong className={styles.orderPackPrice}>
                        {formatCurrency(getPackTotal(pack))}
                      </strong>
                    </div>

                    <div className={styles.orderPackBody}>
                      <h3>{pack.packName}</h3>
                      <p>
                        {pack.schoolName || 'School pack'}
                        {pack.grade ? ` · ${pack.grade}` : ''}
                      </p>
                      <div className={styles.orderPackBadges}>
                        <span>
                          {pack.packMode === 'full'
                            ? 'Full pack'
                            : 'Customised'}
                        </span>
                        <span>
                          {pack.items.length}{' '}
                          {pack.items.length === 1 ? 'item' : 'items'}
                        </span>
                        {pack.wantsPexcover ? <span>Pexcover</span> : null}
                      </div>
                    </div>

                    <button
                      type="button"
                      className={styles.itemsToggle}
                      aria-expanded={isExpanded}
                      aria-controls={`pack-items-${pack.id}`}
                      onClick={() =>
                        setExpandedPacks((prev) => ({
                          ...prev,
                          [pack.id]: !prev[pack.id],
                        }))
                      }
                    >
                      <span>{isExpanded ? 'Hide items' : 'View items'}</span>
                      <span aria-hidden="true">{isExpanded ? '-' : '+'}</span>
                    </button>

                    {isExpanded ? (
                      <ul
                        id={`pack-items-${pack.id}`}
                        className={styles.itemisedList}
                      >
                        {previewItems.map((item, itemIndex) => {
                          const lineTotal = getItemLineTotal(item)
                          return (
                            <li key={`${pack.id}-${item.name}-${itemIndex}`}>
                              <span>{item.name}</span>
                              <span>Qty {item.quantity}</span>
                              {lineTotal !== null ? (
                                <strong>{formatCurrency(lineTotal)}</strong>
                              ) : null}
                            </li>
                          )
                        })}
                        {pack.wantsPexcover ? (
                          <li className={styles.itemisedPexcover}>
                            <span>
                              Pexcover <em>(Book covering)</em>
                            </span>
                            <span />
                            <strong>{formatCurrency(PEXCOVER_PRICE)}</strong>
                          </li>
                        ) : null}
                        {hiddenCount > 0 ? (
                          <li className={styles.itemisedMore}>
                            + {hiddenCount} more items in this pack
                          </li>
                        ) : null}
                      </ul>
                    ) : null}
                  </article>
                )
              })}
            </div>

            <div className={styles.summaryTotals}>
              <div>
                <span>Pack subtotal</span>
                <strong>{formatCurrency(itemsTotal)}</strong>
              </div>
              {pexcoverCount > 0 ? (
                <div className={styles.pexcoverSummary}>
                  <span>
                    Pexcover <em>(Book covering)</em> x{pexcoverCount}
                  </span>
                  <strong>{formatCurrency(pexcoverTotal)}</strong>
                </div>
              ) : null}
              {fulfilmentOption === 'home_delivery' ? (
                <div>
                  <span>Delivery fee</span>
                  <strong>To confirm</strong>
                </div>
              ) : null}
              <div className={styles.summaryGrandTotal}>
                <span>
                  {fulfilmentOption === 'home_delivery'
                    ? 'Pack total payable now'
                    : 'Total payable now'}
                </span>
                <strong>{formatCurrency(total)}</strong>
              </div>
            </div>

            {fulfilmentOption === 'home_delivery' ? (
              <p className={styles.deliveryFeeNotice}>
                The home-delivery fee is not included in this payment. We will
                confirm the fee with you separately before dispatch.
              </p>
            ) : null}

            {errors.packs || errors.total ? (
              <p className={styles.formStatusError} role="alert">
                {errors.packs || errors.total}
              </p>
            ) : null}

            <Button
              type="button"
              variant="primary"
              size="lg"
              className={clsx(styles.fullWidth, styles.desktopPayButton)}
              onClick={handlePay}
              disabled={!canSubmit}
              aria-busy={submitting}
            >
              {submitting
                ? 'Preparing your order...'
                : fulfilmentOption === 'home_delivery'
                  ? `Pay Pack Total ${formatCurrency(total)}`
                  : `Pay Now ${formatCurrency(total)}`}
            </Button>

            <Button
              type="button"
              variant="outline"
              className={styles.fullWidth}
              onClick={handleBackToOrder}
            >
              Edit order
            </Button>

            <p className={styles.summarySecurity}>
              Your order details are secure. Pexpacks will never share your
              information.
            </p>
          </div>
        </aside>
      </div>

      <div className={styles.mobileStickyCta}>
        <Button
          type="button"
          variant="primary"
          className={styles.fullWidth}
          onClick={handlePay}
          disabled={!canSubmit}
          aria-busy={submitting}
        >
          {submitting
            ? 'Preparing...'
            : fulfilmentOption === 'home_delivery'
              ? `Pay Pack Total ${formatCurrency(total)}`
              : `Pay Now ${formatCurrency(total)}`}
        </Button>
      </div>
    </div>
  )
}

