          const currentVis = visibilityMap[s.school_id] ?? (isSchoolActive ? "visible" : "hidden");
          return {
            id: s.school_id,
            code: `SCH-${1001 + idx}`,
            name: s.school_name,
            gradePacksCount: s.grade_packs_count,
            season: "2027",
            lastEdited: formatDateString(s.last_edited),
            lastEditedBy: "Mcebisi M.",
