"use client";

import React, { useState, useMemo } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Plus,
  Search,
  FileSpreadsheet,
  Clock,
  CheckCircle2,
  XCircle,
  TrendingUp,
  Download,
  Eye,
  SlidersHorizontal,
} from "lucide-react";
import {
  AdminPageHeader,
  AdminButton,
  MetricCard,
  StatusBadge,
  type BadgeTone,
} from "@/components/admin/ui";
import { FloatingInput } from "@/components/ui/FloatingInput";
import type { QuotationsListResult } from "@/lib/admin/quotations";
import styles from "./Quotations.module.css";

const STATUS_CONFIG: Record<string, { label: string; tone: BadgeTone }> = {
  draft: { label: "Draft", tone: "slate" },
  sent: { label: "Sent", tone: "blue" },
  accepted: { label: "Accepted", tone: "emerald" },
  declined: { label: "Declined", tone: "red" },
  expired: { label: "Expired", tone: "amber" },
  converted_to_order: { label: "Converted", tone: "teal" },
};

function formatMoney(amount: number): string {
  return `R ${Number(amount || 0).toLocaleString("en-ZA", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

export function QuotationsListView({
  initialData,
}: {
  initialData: QuotationsListResult;
}) {
  const router = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 15;

  const pendingCount = (initialData.stats.sent || 0) + (initialData.stats.draft || 0);

  const filtered = useMemo(() => {
    return initialData.quotations.filter((q) => {
      // 1. Status Filter
      if (statusFilter !== "all" && q.status !== statusFilter) {
        return false;
      }
      // 2. Search Query
      if (searchQuery.trim()) {
        const query = searchQuery.toLowerCase();
        const numMatch = q.quote_number.toLowerCase().includes(query);
        const nameMatch = q.recipient_name.toLowerCase().includes(query);
        const emailMatch = q.recipient_email.toLowerCase().includes(query);
        const schoolMatch = q.school?.name?.toLowerCase().includes(query);
        return numMatch || nameMatch || emailMatch || Boolean(schoolMatch);
      }
      return true;
    });
  }, [initialData.quotations, statusFilter, searchQuery]);

  const totalPages = Math.ceil(filtered.length / pageSize) || 1;
  const paginated = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filtered.slice(start, start + pageSize);
  }, [filtered, currentPage, pageSize]);

  return (
    <div className={styles.container}>
      {/* 1. Header Toolbar */}
      <AdminPageHeader
        title="Quotations"
        count={initialData.stats.total}
        subtitle="Create branded A4 quotations, track quote statuses, and convert to official orders."
        actions={
          <>
            <AdminButton
              variant="secondary"
              href="/admin/quotations/pexpacks-details"
              icon={<SlidersHorizontal size={14} />}
            >
              Pexpacks Details
            </AdminButton>
            <AdminButton
              variant="primary"
              href="/admin/quotations/new"
              icon={<Plus size={15} />}
            >
              New Quotation
            </AdminButton>
          </>
        }
      />

      {/* 2. 5 KPI Summary Cards */}
      <div className={styles.kpiGrid5}>
        <MetricCard
          label="Total Quotes"
          value={initialData.stats.total}
          icon={<FileSpreadsheet size={16} />}
          iconTone="blue"
          subtext="Generated in season"
        />
        <MetricCard
          label="Awaiting Acceptance"
          value={pendingCount}
          icon={<Clock size={16} />}
          iconTone="amber"
          subtext="Sent to clients"
        />
        <MetricCard
          label="Accepted Quotes"
          value={initialData.stats.accepted}
          icon={<CheckCircle2 size={16} />}
          iconTone="green"
          subtext="Ready for conversion"
        />
        <MetricCard
          label="Declined"
          value={initialData.stats.declined}
          icon={<XCircle size={16} />}
          iconTone="red"
          subtext="Unsuccessful quotes"
        />
        <MetricCard
          label="Converted to Orders"
          value={initialData.stats.converted}
          icon={<TrendingUp size={16} />}
          iconTone="green"
          subtext="Live orders"
        />
      </div>

      {/* 3. Search & Status Tabs */}
      <div className={styles.toolbarRow}>
        <div className={styles.searchWrapper}>
          <FloatingInput
            label="Search Quote #, recipient, or school..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setCurrentPage(1);
            }}
            icon={<Search size={15} />}
          />
        </div>

        <div className={styles.statusTabs}>
          {[
            { id: "all", label: "All" },
            { id: "draft", label: "Draft" },
            { id: "sent", label: "Sent" },
            { id: "accepted", label: "Accepted" },
            { id: "declined", label: "Declined" },
            { id: "converted_to_order", label: "Converted" },
          ].map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => {
                setStatusFilter(tab.id);
                setCurrentPage(1);
              }}
              className={`${styles.statusTab} ${statusFilter === tab.id ? styles.statusTabActive : ""}`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* 4. Quotations Data Table */}
      <div className={styles.tableCard}>
        <div className={styles.tableWrapper}>
          <table className={styles.dataTable}>
            <thead>
              <tr>
                <th>Quote Number</th>
                <th>Client / School</th>
                <th>Created</th>
                <th>Valid Until</th>
                <th>Items</th>
                <th>Total (ZAR)</th>
                <th>Status</th>
                <th style={{ textAlign: "right" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {paginated.length === 0 ? (
                <tr>
                  <td colSpan={8} className={styles.emptyTableState}>
                    No quotations found matching your criteria.
                  </td>
                </tr>
              ) : (
                paginated.map((quote) => {
                  const cfg = STATUS_CONFIG[quote.status] || { label: quote.status, tone: "slate" as BadgeTone };
                  return (
                    <tr
                      key={quote.id}
                      className={styles.dataRow}
                      onClick={() => router.push(`/admin/quotations/${quote.quote_number}`)}
                    >
                      <td>
                        <Link
                          href={`/admin/quotations/${quote.quote_number}`}
                          className={styles.quoteNumLink}
                          onClick={(e) => e.stopPropagation()}
                        >
                          {quote.quote_number}
                        </Link>
                      </td>
                      <td>
                        <div className={styles.recipientCell}>
                          <span className={styles.recipientName}>{quote.recipient_name}</span>
                          <span className={styles.schoolSubtext}>
                            {quote.school?.name || quote.recipient_email}
                          </span>
                        </div>
                      </td>
                      <td className={styles.textMuted}>
                        {new Date(quote.created_at).toLocaleDateString("en-ZA")}
                      </td>
                      <td className={styles.textMuted}>
                        {new Date(quote.valid_until).toLocaleDateString("en-ZA")}
                      </td>
                      <td className={styles.textMuted}>
                        {quote.items_count} {quote.items_count === 1 ? "item" : "items"}
                      </td>
                      <td className={styles.priceText}>{formatMoney(quote.total_amount)}</td>
                      <td>
                        <StatusBadge status={cfg.label} tone={cfg.tone} showDot />
                      </td>
                      <td onClick={(e) => e.stopPropagation()} className={styles.tableActionsCell}>
                        <div className={styles.tableActionsGroup}>
                          <AdminButton
                            variant="secondary"
                            size="sm"
                            href={`/admin/quotations/${quote.quote_number}`}
                            icon={<Eye size={12} />}
                          >
                            View
                          </AdminButton>
                          {quote.pdf_storage_path ? (
                            <AdminButton
                              variant="outline"
                              size="sm"
                              href={quote.pdf_storage_path}
                              target="_blank"
                              rel="noopener noreferrer"
                              icon={<Download size={12} />}
                            >
                              PDF
                            </AdminButton>
                          ) : null}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition, useMemo } from "react";
import {
  UserPlus,
  User,
  Building,
  Shield,
  Send,
  CheckCircle2,
  AlertCircle,
  Info,
  Clock,
  Check,
} from "lucide-react";
import { FloatingInput } from "@/components/ui/FloatingInput";
import { FloatingTextarea } from "@/components/ui/FloatingTextarea";
import { inviteUserFromSettingsAction } from "@/app/admin/settings/actions";
import type { RoleInfo } from "@/lib/admin/users";
import adminStyles from "@/app/admin/admin.module.css";

interface AddUsersTabProps {
  roles: RoleInfo[];
  currentUserEmail?: string;
  isSuperUser?: boolean;
}

const DEPARTMENTS = [
  "Executive & Management",
  "School Relationships & Partnerships",
  "Procurement & Supply Chain",
  "Warehouse & Order Fulfilment",
  "Finance & Accounts",
  "Customer Support & Success",
  "Catalog & Content Management",
];

export function AddUsersTab({
  roles,
  currentUserEmail,
  isSuperUser = false,
}: AddUsersTabProps) {
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [department, setDepartment] = useState(DEPARTMENTS[0]);
  const [selectedRoles, setSelectedRoles] = useState<string[]>(["viewer"]);
  const [notes, setNotes] = useState("");
  const [isPending, startTransition] = useTransition();
  const [statusMessage, setStatusMessage] = useState<{
    type: "success" | "error";
    text: string;
    tempPassword?: string;
  } | null>(null);
  const [copiedTemp, setCopiedTemp] = useState(false);

  // Superuser role is strictly only visible to the 2 designated superusers
  const visibleRoles = useMemo<RoleInfo[]>(() => {
    return (roles || []).filter((r: RoleInfo) => {
      const isSuperRole = r.slug === "super_admin" || r.slug === "superuser";
      if (isSuperRole) {
        return isSuperUser;
      }
      return true;
    });
  }, [roles, isSuperUser]);

  function toggleRole(slug: string) {
    setSelectedRoles((prev) =>
      prev.includes(slug) ? prev.filter((r) => r !== slug) : [...prev, slug]
    );
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setStatusMessage(null);
    setCopiedTemp(false);

    const formData = new FormData();
    formData.append("full_name", fullName);
    formData.append("email", email);
    formData.append("department", department);
    formData.append("notes", notes);
    for (const r of selectedRoles) {
      formData.append("roles", r);
    }

    startTransition(async () => {
      const res = await inviteUserFromSettingsAction(formData);
      if (res.ok) {
        setStatusMessage({
          type: "success",
          text: res.message || "Invitation successfully dispatched!",
          tempPassword: res.tempPassword,
        });
        setFullName("");
        setEmail("");
        setNotes("");
        setSelectedRoles(["viewer"]);
      } else {
        setStatusMessage({
          type: "error",
          text: res.message || "Failed to dispatch user invitation.",
        });
      }
    });
  }

  function handleCopyTempPassword(pwd: string) {
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        void navigator.clipboard.writeText(pwd);
        setCopiedTemp(true);
        setTimeout(() => setCopiedTemp(false), 2000);
      }
    } catch {
      // ignore
    }
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
      {/* Header Banner */}
      <div
        style={{
          background: "linear-gradient(135deg, rgba(16, 185, 129, 0.1) 0%, rgba(9, 14, 23, 0.95) 100%)",
          border: "1px solid rgba(16, 185, 129, 0.25)",
          borderRadius: "14px",
          padding: "24px 28px",
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          gap: "20px",
        }}
      >
        <div style={{ maxWidth: "640px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "8px" }}>
            <div
              style={{
                width: "32px",
                height: "32px",
                borderRadius: "8px",
                backgroundColor: "rgba(16, 185, 129, 0.2)",
                color: "#10b981",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <UserPlus size={18} />
            </div>
            <h2 style={{ fontSize: "1.25rem", fontWeight: 700, color: "#ffffff", margin: 0 }}>
              Add Users &amp; Team Onboarding
            </h2>
          </div>
          <p style={{ fontSize: "0.875rem", color: "#94a3b8", lineHeight: 1.6, margin: 0 }}>
            Empower new administrators and team members with tailored access. Newly invited users
            receive an automated, branded onboarding email with their assigned roles, temporary password,
            and login gateway. Upon first sign in, they will establish their permanent password.
          </p>
        </div>

        <div
          style={{
            background: "rgba(15, 23, 42, 0.8)",
            border: "1px solid rgba(51, 65, 85, 0.6)",
            borderRadius: "10px",
            padding: "12px 16px",
            textAlign: "center",
            minWidth: "160px",
          }}
        >
          <div style={{ fontSize: "11px", fontWeight: 600, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.05em" }}>
            Available Roles
          </div>
          <div style={{ fontSize: "1.5rem", fontWeight: 800, color: "#10b981", marginTop: "2px" }}>
            {roles.length || 7}
          </div>
          <div style={{ fontSize: "11px", color: "#94a3b8" }}>Configured in RBAC</div>
        </div>
      </div>

      {/* Status Feedback Banner */}
      {statusMessage && (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "10px",
            padding: "16px 20px",
            borderRadius: "10px",
            backgroundColor:
              statusMessage.type === "success"
                ? "rgba(16, 185, 129, 0.12)"
                : "rgba(239, 68, 68, 0.15)",
            border:
              statusMessage.type === "success"
                ? "1px solid rgba(16, 185, 129, 0.35)"
                : "1px solid rgba(239, 68, 68, 0.35)",
            color: statusMessage.type === "success" ? "#34d399" : "#f87171",
            fontSize: "0.875rem",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: "10px", fontWeight: 600 }}>
            {statusMessage.type === "success" ? (
              <CheckCircle2 size={18} />
            ) : (
              <AlertCircle size={18} />
            )}
            <span>{statusMessage.text}</span>
          </div>

          {statusMessage.tempPassword && (
            <div
              style={{
                backgroundColor: "rgba(15, 23, 42, 0.9)",
                border: "1px solid rgba(59, 130, 246, 0.4)",
                borderRadius: "8px",
                padding: "10px 14px",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                flexWrap: "wrap",
                gap: "10px",
                marginTop: "4px",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "0.8125rem", color: "#cbd5e1" }}>
                <span>🔐 Generated Temporary Password:</span>
                <span
                  style={{
                    fontFamily: "monospace",
                    fontWeight: 700,
                    color: "#38bdf8",
                    backgroundColor: "rgba(59, 130, 246, 0.15)",
                    padding: "3px 8px",
                    borderRadius: "4px",
                    letterSpacing: "0.05em",
                  }}
                >
                  {statusMessage.tempPassword}
                </span>
              </div>

              <button
                type="button"
                onClick={() => handleCopyTempPassword(statusMessage.tempPassword!)}
                style={{
                  backgroundColor: copiedTemp ? "#10b981" : "rgba(59, 130, 246, 0.2)",
                  border: copiedTemp ? "1px solid #10b981" : "1px solid rgba(59, 130, 246, 0.4)",
                  color: "#ffffff",
                  borderRadius: "6px",
                  padding: "4px 10px",
                  fontSize: "0.75rem",
                  fontWeight: 600,
                  cursor: "pointer",
                  display: "flex",
                  alignItems: "center",
                  gap: "6px",
                }}
              >
                {copiedTemp ? <Check size={12} strokeWidth={3} /> : null}
                <span>{copiedTemp ? "Copied!" : "Copy Password"}</span>
              </button>
            </div>
          )}
        </div>
      )}

      {/* Main Onboarding Form Card */}
      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
        <div className={adminStyles.tableCard} style={{ padding: "28px", display: "flex", flexDirection: "column", gap: "24px" }}>

          {/* Section 1: Core Information */}
          <div>
            <h3 style={{ fontSize: "0.9375rem", fontWeight: 700, color: "#f8fafc", margin: "0 0 4px", display: "flex", alignItems: "center", gap: "8px" }}>
              <User size={16} style={{ color: "#10b981" }} />
              1. Essential User Credentials
            </h3>
            <p style={{ fontSize: "0.8125rem", color: "#64748b", margin: "0 0 18px" }}>
              Mandatory contact information for system recognition, email dispatch, and dashboard greeting.
            </p>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: "20px" }}>
              <FloatingInput
                id="user_full_name"
                label="Full Name *"
                type="text"
                required
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                placeholder="e.g. Thandi Nkosi"
                disabled={isPending}
                bgSurface="#0c1322"
              />

              <FloatingInput
                id="user_email"
                label="Email Address *"
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="e.g. thandi@pexpacks.co.za"
                disabled={isPending}
                bgSurface="#0c1322"
              />
            </div>
          </div>

          <div style={{ height: "1px", backgroundColor: "rgba(51, 65, 85, 0.4)" }} />

          {/* Section 2: Department & Assignment */}
          <div>
            <h3 style={{ fontSize: "0.9375rem", fontWeight: 700, color: "#f8fafc", margin: "0 0 4px", display: "flex", alignItems: "center", gap: "8px" }}>
              <Building size={16} style={{ color: "#38bdf8" }} />
              2. Department &amp; Organizational Role
            </h3>
            <p style={{ fontSize: "0.8125rem", color: "#64748b", margin: "0 0 18px" }}>
              Categorizes the user within Pexpacks Supplies for operational workflows and reporting.
            </p>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: "20px" }}>
              <div>
                <label style={{ display: "block", fontSize: "0.8125rem", fontWeight: 600, color: "#94a3b8", marginBottom: "8px" }}>
                  Operational Department
                </label>
                <select
                  value={department}
                  onChange={(e) => setDepartment(e.target.value)}
                  disabled={isPending}
                  style={{
                    width: "100%",
                    height: "46px",
                    backgroundColor: "#090e17",
                    border: "1px solid rgba(51, 65, 85, 0.8)",
                    borderRadius: "8px",
                    color: "#ffffff",
                    padding: "0 14px",
                    fontSize: "0.875rem",
                    fontWeight: 500,
                    outline: "none",
                  }}
                >
                  {DEPARTMENTS.map((dept) => (
                    <option key={dept} value={dept}>
                      {dept}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <FloatingTextarea
                  id="user_notes"
                  label="Personalized Welcome Note / Special Instructions (Optional)"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  rows={2}
                  placeholder="e.g. Welcome to the Q3 Back-to-School season team! Please complete your 2FA setup upon login."
                  disabled={isPending}
                  bgSurface="#0c1322"
                />
              </div>
            </div>
          </div>

          <div style={{ height: "1px", backgroundColor: "rgba(51, 65, 85, 0.4)" }} />

          {/* Section 3: Role & Permission Assignment */}
          <div>
            <h3 style={{ fontSize: "0.9375rem", fontWeight: 700, color: "#f8fafc", margin: "0 0 4px", display: "flex", alignItems: "center", gap: "8px" }}>
              <Shield size={16} style={{ color: "#a855f7" }} />
              3. Role &amp; Permission Access
            </h3>
            <p style={{ fontSize: "0.8125rem", color: "#64748b", margin: "0 0 18px" }}>
              Select one or more roles that define what modules and actions this user can perform in the Back-Office.
            </p>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: "12px" }}>
              {visibleRoles.map((role) => {
                const isSelected = selectedRoles.includes(role.slug);
                const isSuper = role.slug === "super_admin" || role.slug === "superuser";

                return (
                  <div
                    key={role.id}
                    onClick={() => toggleRole(role.slug)}
                    style={{
                      backgroundColor: isSelected
                        ? isSuper
                          ? "rgba(168, 85, 247, 0.15)"
                          : "rgba(16, 185, 129, 0.1)"
                        : isSuper
                        ? "rgba(168, 85, 247, 0.04)"
                        : "#090e17",
                      border: isSelected
                        ? isSuper
                          ? "1px solid #c084fc"
                          : "1px solid #10b981"
                        : isSuper
                        ? "1px solid rgba(168, 85, 247, 0.4)"
                        : "1px solid rgba(51, 65, 85, 0.6)",
                      borderRadius: "10px",
                      padding: "14px 16px",
                      cursor: "pointer",
                      transition: "all 0.15s ease",
                      display: "flex",
                      flexDirection: "column",
                      justifyContent: "space-between",
                      gap: "8px",
                      position: "relative",
                    }}
                  >
                    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                        {isSuper && <Shield size={14} style={{ color: "#c084fc" }} />}
                        <span
                          style={{
                            fontSize: "0.875rem",
                            fontWeight: 700,
                            color: isSelected
                              ? isSuper
                                ? "#e9d5ff"
                                : "#34d399"
                              : isSuper
                              ? "#c084fc"
                              : "#ffffff",
                          }}
                        >
                          {isSuper ? "Superuser" : role.name}
                        </span>
                      </div>

                      <div
                        style={{
                          width: "18px",
                          height: "18px",
                          borderRadius: "4px",
                          border: isSelected
                            ? isSuper
                              ? "1px solid #a855f7"
                              : "1px solid #10b981"
                            : "1px solid #475569",
                          backgroundColor: isSelected
                            ? isSuper
                              ? "#a855f7"
                              : "#10b981"
                            : "transparent",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          color: "#ffffff",
                        }}
                      >
                        {isSelected && <Check size={12} strokeWidth={3} />}
                      </div>
                    </div>

                    {isSuper && (
                      <div style={{ display: "inline-block" }}>
                        <span
                          style={{
                            fontSize: "10px",
                            fontWeight: 800,
                            textTransform: "uppercase",
                            padding: "2px 6px",
                            borderRadius: "4px",
                            backgroundColor: "rgba(168, 85, 247, 0.25)",
                            color: "#e9d5ff",
                            letterSpacing: "0.04em",
                          }}
                        >
                          👑 Superuser Access Add-on
                        </span>
                      </div>
                    )}

                    <p style={{ fontSize: "0.75rem", color: "#94a3b8", lineHeight: 1.4, margin: 0 }}>
                      {isSuper
                        ? "Full unrestricted access across all DB modules & settings. Max 2 accounts permitted."
                        : role.description || "General platform access and permissions."}
                    </p>
                  </div>
                );
              })}
            </div>
          </div>

          <div style={{ height: "1px", backgroundColor: "rgba(51, 65, 85, 0.4)" }} />

          {/* Submit Action */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: "16px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "0.8125rem", color: "#64748b" }}>
              <Info size={14} />
              <span>An automated invitation email with role details will be sent immediately upon submission.</span>
            </div>

            <button
              type="submit"
              disabled={isPending || !fullName.trim() || !email.trim()}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "10px",
                height: "44px",
                padding: "0 24px",
                backgroundColor: isPending || !fullName.trim() || !email.trim() ? "#1e293b" : "#10b981",
                color: isPending || !fullName.trim() || !email.trim() ? "#64748b" : "#ffffff",
                border: "none",
                borderRadius: "8px",
                fontSize: "0.875rem",
                fontWeight: 700,
                cursor: isPending || !fullName.trim() || !email.trim() ? "not-allowed" : "pointer",
                boxShadow: isPending || !fullName.trim() || !email.trim() ? "none" : "0 4px 14px rgba(16, 185, 129, 0.3)",
                transition: "all 0.15s ease",
              }}
            >
              {isPending ? (
                <>
                  <Clock size={16} className="animate-spin" /> Dispatching Invitation...
                </>
              ) : (
                <>
                  <Send size={16} /> Dispatch Invitation &amp; Onboard User
                </>
              )}
            </button>
          </div>

        </div>
      </form>
    </div>
  );
}

"use client";

import { useState, useMemo, useTransition } from "react";
import { useRouter } from "next/navigation";
import {

  Lock,
  KeyRound,
  Eye,
  EyeOff,
  Copy,
  Check,
  Trash2,
  Edit2,
  Search,
  CheckCircle2,
  AlertCircle,
  RefreshCw,
} from "lucide-react";
import type { SystemVaultCredential } from "@/lib/admin/system-settings-shared";
import {
  saveVaultCredentialAction,
  deleteVaultCredentialAction,
} from "@/app/admin/settings/actions";
import styles from "./SettingsControlCentre.module.css";

interface SystemInfoVaultTabProps {
  initialVaultCredentials?: SystemVaultCredential[];
  userEmail: string;
}

const VAULT_CATEGORIES = [
  "Database",
  "API Service",
  "Authentication",
  "Payment Gateway",
  "Cloud & Hosting",
  "Other Operations",
];

export function SystemInfoVaultTab({
  initialVaultCredentials = [],
  userEmail,
}: SystemInfoVaultTabProps) {
  const router = useRouter();
  const [credentials, setCredentials] = useState<SystemVaultCredential[]>(
    initialVaultCredentials
  );
  const [searchQuery, setSearchQuery] = useState("");
  const [isPending, startTransition] = useTransition();

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [productName, setProductName] = useState("");
  const [category, setCategory] = useState("Database");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [additionalInfo, setAdditionalInfo] = useState("");
  const [formPasswordVisible, setFormPasswordVisible] = useState(false);

  // Card Reveal States
  const [revealedIds, setRevealedIds] = useState<Set<string>>(new Set());
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Status Feedback
  const [feedback, setFeedback] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  const filteredCredentials = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return credentials;
    return credentials.filter(
      (c) =>
        c.productName.toLowerCase().includes(q) ||
        c.username.toLowerCase().includes(q) ||
        c.category.toLowerCase().includes(q) ||
        (c.additionalInfo || "").toLowerCase().includes(q)
    );
  }, [credentials, searchQuery]);

  function toggleReveal(id: string) {
    setRevealedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function handleCopy(text: string, id: string) {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  }

  function handleStartEdit(cred: SystemVaultCredential) {
    setEditingId(cred.id);
    setProductName(cred.productName);
    setCategory(cred.category || "Database");
    setUsername(cred.username);
    setPassword(cred.password);
    setAdditionalInfo(cred.additionalInfo || "");
    setFeedback(null);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function handleCancelEdit() {
    setEditingId(null);
    setProductName("");
    setCategory("Database");
    setUsername("");
    setPassword("");
    setAdditionalInfo("");
    setFeedback(null);
  }

  function handleSave(e: React.FormEvent) {
    e.preventDefault();
    setFeedback(null);

    if (!productName.trim()) {
      setFeedback({ type: "error", text: "Product / Service name is required." });
      return;
    }
    if (!username.trim()) {
      setFeedback({ type: "error", text: "Username / Client ID is required." });
      return;
    }
    if (!password.trim()) {
      setFeedback({ type: "error", text: "Password / Secret token is required." });
      return;
    }

    startTransition(async () => {
      const res = await saveVaultCredentialAction({
        id: editingId || undefined,
        productName,
        category,
        username,
        password,
        additionalInfo,
      });

      if (res.ok && res.credentials) {
        setCredentials(res.credentials);
        setFeedback({
          type: "success",
          text: `Credential record for "${productName}" securely saved to vault.`,
        });
        handleCancelEdit();
        router.refresh();
      } else {
        setFeedback({
          type: "error",
          text: res.message || "Failed to save credential.",
        });
      }
    });
  }

  function handleDelete(id: string, name: string) {
    if (!confirm(`Are you sure you want to permanently delete the vault credential for "${name}"?`)) {
      return;
    }
    setFeedback(null);

    startTransition(async () => {
      const res = await deleteVaultCredentialAction(id);
      if (res.ok && res.credentials) {
        setCredentials(res.credentials);
        setFeedback({
          type: "success",
          text: `Credential for "${name}" removed from vault.`,
        });
        if (editingId === id) handleCancelEdit();
        router.refresh();
      } else {
        setFeedback({
          type: "error",
          text: res.message || "Failed to delete credential.",
        });
      }
    });
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "28px" }}>
      {/* Security & Shield Banner */}
      <div
        style={{
          background: "linear-gradient(135deg, rgba(168, 85, 247, 0.12) 0%, rgba(9, 14, 23, 0.95) 100%)",
          border: "1px solid rgba(168, 85, 247, 0.35)",
          borderRadius: "14px",
          padding: "24px 28px",
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          gap: "20px",
        }}
      >
        <div style={{ maxWidth: "680px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "8px" }}>
            <div
              style={{
                width: "32px",
                height: "32px",
                borderRadius: "8px",
                backgroundColor: "rgba(168, 85, 247, 0.2)",
                color: "#c084fc",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <Lock size={18} />
            </div>
            <h2 style={{ fontSize: "1.25rem", fontWeight: 700, color: "#ffffff", margin: 0 }}>
              Secure System &amp; Database Vault
            </h2>
            <span
              style={{
                fontSize: "10px",
                fontWeight: 800,
                textTransform: "uppercase",
                padding: "2px 8px",
                borderRadius: "4px",
                backgroundColor: "rgba(168, 85, 247, 0.25)",
                color: "#e9d5ff",
                letterSpacing: "0.05em",
              }}
            >
              Superuser Gated
            </span>
          </div>
          <p style={{ fontSize: "0.875rem", color: "#94a3b8", lineHeight: 1.6, margin: 0 }}>
            Encrypted vault designated for safely storing and referencing sensitive credentials, database keys,
            and operational parameters. Records are strictly accessible to authorized Superusers and masked by default.
          </p>
        </div>

        <div style={{ display: "flex", gap: "12px" }}>
          <div
            style={{
              background: "rgba(15, 23, 42, 0.8)",
              border: "1px solid rgba(51, 65, 85, 0.6)",
              borderRadius: "10px",
              padding: "12px 18px",
              textAlign: "center",
            }}
          >
            <div style={{ fontSize: "11px", fontWeight: 600, color: "#64748b", textTransform: "uppercase" }}>
              Vault Records
            </div>
            <div style={{ fontSize: "1.5rem", fontWeight: 800, color: "#c084fc", marginTop: "2px" }}>
              {credentials.length}
            </div>
          </div>
        </div>
      </div>

      {/* Feedback Alert */}
      {feedback && (
        <div
          style={{
            padding: "14px 18px",
            borderRadius: "10px",
            backgroundColor:
              feedback.type === "success"
                ? "rgba(16, 185, 129, 0.15)"
                : "rgba(239, 68, 68, 0.15)",
            border:
              feedback.type === "success"
                ? "1px solid rgba(16, 185, 129, 0.35)"
                : "1px solid rgba(239, 68, 68, 0.35)",
            color: feedback.type === "success" ? "#34d399" : "#f87171",
            fontSize: "0.875rem",
            fontWeight: 600,
            display: "flex",
            alignItems: "center",
            gap: "10px",
          }}
        >
          {feedback.type === "success" ? (
            <CheckCircle2 size={18} />
          ) : (
            <AlertCircle size={18} />
          )}
          <span>{feedback.text}</span>
        </div>
      )}

      {/* Input / Edit Form Card */}
      <div className={styles.panelCard}>
        <div className={styles.panelHeader}>
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <KeyRound size={20} style={{ color: "#38bdf8" }} />
            <div>
              <h2 style={{ margin: 0 }}>
                {editingId ? "Edit Vault Credential Record" : "Input New System Credential"}
              </h2>
              <p style={{ margin: "2px 0 0" }}>
                {editingId
                  ? "Update the selected database or operational service credentials"
                  : "Enter the product name, username, password, and additional context to safely store in the DB"}
              </p>
            </div>
          </div>
        </div>

        <form onSubmit={handleSave} style={{ display: "flex", flexDirection: "column", gap: "18px" }}>
          <div className={styles.formGrid}>
            {/* Product Name */}
            <div className={styles.field}>
              <label className={styles.label}>
                Product / Service / Provider Name <span style={{ color: "#ef4444" }}>*</span>
              </label>
              <input
                type="text"
                className={styles.input}
                placeholder="e.g. Supabase DB Production, Resend API, Vercel Host..."
                value={productName}
                onChange={(e) => setProductName(e.target.value)}
                maxLength={120}
                required
              />
              <span className={styles.hint}>Target system, database cluster, or external SaaS service.</span>
            </div>

            {/* Category */}
            <div className={styles.field}>
              <label className={styles.label}>Module Category</label>
              <select
                className={styles.select}
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              >
                {VAULT_CATEGORIES.map((cat) => (
                  <option key={cat} value={cat}>
                    {cat}
                  </option>
                ))}
              </select>
              <span className={styles.hint}>Grouping for organized referencing and filtering.</span>
            </div>

            {/* Username / Account */}
            <div className={styles.field}>
              <label className={styles.label}>
                Username / Client ID / Account Key <span style={{ color: "#ef4444" }}>*</span>
              </label>
              <input
                type="text"
                className={styles.input}
                placeholder="e.g. postgres, admin@pexpacks.co.za, app_client_id..."
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                maxLength={120}
                required
              />
              <span className={styles.hint}>Authorized principal or service account login username.</span>
            </div>

            {/* Password / Secret */}
            <div className={styles.field}>
              <label className={styles.label}>
                Password / Secret Token / Private Key <span style={{ color: "#ef4444" }}>*</span>
              </label>
              <div style={{ position: "relative" }}>
                <input
                  type={formPasswordVisible ? "text" : "password"}
                  className={styles.input}
                  placeholder="Enter secure password or secret..."
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  maxLength={500}
                  style={{ paddingRight: "44px" }}
                  required
                />
                <button
                  type="button"
                  onClick={() => setFormPasswordVisible((v) => !v)}
                  style={{
                    position: "absolute",
                    right: "12px",
                    top: "50%",
                    transform: "translateY(-50%)",
                    background: "transparent",
                    border: "none",
                    color: "#64748b",
                    cursor: "pointer",
                    padding: "4px",
                    display: "flex",
                    alignItems: "center",
                  }}
                  title={formPasswordVisible ? "Hide password" : "Show password"}
                >
                  {formPasswordVisible ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
              <span className={styles.hint}>Stored with encryption; masked on display.</span>
            </div>
          </div>

          {/* Additional Relevant Information */}
          <div className={styles.field}>
            <label className={styles.label}>Additional Relevant Information &amp; Operational Notes</label>
            <textarea
              className={styles.textarea}
              rows={3}
              placeholder="e.g. Host URI: db.rjuvicgqwryztwytnauo.supabase.co | Port: 5432 | Region: eu-west-1 | Failover notes..."
              value={additionalInfo}
              onChange={(e) => setAdditionalInfo(e.target.value)}
              maxLength={1000}
            />
            <span className={styles.hint}>
              Include connection URIs, port numbers, regional endpoints, or backup procedures.
            </span>
          </div>

          {/* Form Actions */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: "12px", marginTop: "8px" }}>
            {editingId && (
              <button
                type="button"
                className={styles.discardButton}
                onClick={handleCancelEdit}
                disabled={isPending}
              >
                Cancel Edit
              </button>
            )}

            <button
              type="submit"
              className={styles.saveButton}
              disabled={isPending}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "8px",
                padding: "10px 24px",
                fontSize: "0.875rem",
                fontWeight: 700,
              }}
            >
              {isPending ? (
                <>
                  <RefreshCw size={15} className="animate-spin" /> Saving...
                </>
              ) : (
                <>
                  <CheckCircle2 size={15} /> {editingId ? "Update Vault Record" : "Save Credential Record"}
                </>
              )}
            </button>
          </div>
        </form>
      </div>

      {/* Structured Stored Records Display */}
      <div style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: "16px",
            flexWrap: "wrap",
          }}
        >
          <div>
            <h3 style={{ fontSize: "1.125rem", fontWeight: 700, color: "#ffffff", margin: 0 }}>
              Structured Stored Credentials
            </h3>
            <p style={{ fontSize: "0.8125rem", color: "#64748b", margin: "2px 0 0" }}>
              Encrypted credentials stored in the DB. Click reveal to view passwords or copy directly.
            </p>
          </div>

          <div style={{ position: "relative", width: "100%", maxWidth: "340px" }}>
            <Search
              size={15}
              style={{
                position: "absolute",
                left: "12px",
                top: "50%",
                transform: "translateY(-50%)",
                color: "#64748b",
              }}
            />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search stored credentials..."
              style={{
                width: "100%",
                height: "38px",
                paddingLeft: "36px",
                paddingRight: "12px",
                backgroundColor: "#090e17",
                border: "1px solid rgba(51, 65, 85, 0.7)",
                borderRadius: "8px",
                color: "#ffffff",
                fontSize: "0.8125rem",
                outline: "none",
              }}
            />
          </div>
        </div>

        {filteredCredentials.length > 0 ? (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(360px, 1fr))", gap: "16px" }}>
            {filteredCredentials.map((cred) => {
              const isRevealed = revealedIds.has(cred.id);
              const isCopied = copiedId === cred.id;

              return (
                <div
                  key={cred.id}
                  style={{
                    backgroundColor: "#090e17",
                    border: "1px solid rgba(51, 65, 85, 0.7)",
                    borderRadius: "12px",
                    padding: "20px",
                    display: "flex",
                    flexDirection: "column",
                    gap: "16px",
                    boxShadow: "0 4px 12px rgba(0, 0, 0, 0.3)",
                  }}
                >
                  {/* Card Header */}
                  <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: "12px" }}>
                    <div>
                      <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                        <h4 style={{ fontSize: "1rem", fontWeight: 700, color: "#ffffff", margin: 0 }}>
                          {cred.productName}
                        </h4>
                      </div>
                      <span
                        style={{
                          display: "inline-block",
                          marginTop: "6px",
                          fontSize: "10px",
                          fontWeight: 700,
                          textTransform: "uppercase",
                          padding: "2px 8px",
                          borderRadius: "4px",
                          backgroundColor: "rgba(56, 189, 248, 0.15)",
                          border: "1px solid rgba(56, 189, 248, 0.3)",
                          color: "#38bdf8",
                        }}
                      >
                        {cred.category || "Database"}
                      </span>
                    </div>

                    <div style={{ display: "flex", gap: "6px" }}>
                      <button
                        type="button"
                        onClick={() => handleStartEdit(cred)}
                        style={{
                          background: "rgba(51, 65, 85, 0.4)",
                          border: "1px solid rgba(71, 85, 105, 0.6)",
                          borderRadius: "6px",
                          padding: "6px 8px",
                          color: "#94a3b8",
                          cursor: "pointer",
                          display: "flex",
                          alignItems: "center",
                          gap: "4px",
                          fontSize: "11px",
                        }}
                        title="Edit credential"
                      >
                        <Edit2 size={12} /> Edit
                      </button>
                      <button
                        type="button"
                        onClick={() => handleDelete(cred.id, cred.productName)}
                        style={{
                          background: "rgba(239, 68, 68, 0.1)",
                          border: "1px solid rgba(239, 68, 68, 0.3)",
                          borderRadius: "6px",
                          padding: "6px 8px",
                          color: "#f87171",
                          cursor: "pointer",
                          display: "flex",
                          alignItems: "center",
                          gap: "4px",
                          fontSize: "11px",
                        }}
                        title="Delete credential"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  </div>

                  {/* Details Grid */}
                  <div style={{ display: "flex", flexDirection: "column", gap: "10px", backgroundColor: "#060a10", padding: "12px", borderRadius: "8px", border: "1px solid rgba(30, 41, 59, 0.8)" }}>
                    {/* Username */}
                    <div>
                      <div style={{ fontSize: "11px", color: "#64748b", fontWeight: 600, textTransform: "uppercase" }}>
                        Username / Account ID
                      </div>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: "2px" }}>
                        <code style={{ fontSize: "12px", color: "#38bdf8", wordBreak: "break-all" }}>
                          {cred.username}
                        </code>
                        <button
                          type="button"
                          onClick={() => handleCopy(cred.username, `${cred.id}-user`)}
                          style={{
                            background: "transparent",
                            border: "none",
                            color: copiedId === `${cred.id}-user` ? "#34d399" : "#64748b",
                            cursor: "pointer",
                            padding: "2px 6px",
                          }}
                          title="Copy username"
                        >
                          {copiedId === `${cred.id}-user` ? <Check size={13} /> : <Copy size={13} />}
                        </button>
                      </div>
                    </div>

                    {/* Password / Secret */}
                    <div style={{ borderTop: "1px solid rgba(30, 41, 59, 0.6)", paddingTop: "8px" }}>
                      <div style={{ fontSize: "11px", color: "#64748b", fontWeight: 600, textTransform: "uppercase" }}>
                        Password / Secret Token
                      </div>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "8px", marginTop: "2px" }}>
                        <code
                          style={{
                            fontSize: "12px",
                            color: isRevealed ? "#f8fafc" : "#94a3b8",
                            fontFamily: "monospace",
                            wordBreak: "break-all",
                          }}
                        >
                          {isRevealed ? cred.password : "••••••••••••••••"}
                        </code>

                        <div style={{ display: "flex", alignItems: "center", gap: "4px", flexShrink: 0 }}>
                          <button
                            type="button"
                            onClick={() => toggleReveal(cred.id)}
                            style={{
                              background: "rgba(51, 65, 85, 0.5)",
                              border: "none",
                              borderRadius: "4px",
                              color: isRevealed ? "#38bdf8" : "#94a3b8",
                              cursor: "pointer",
                              padding: "4px 6px",
                              display: "flex",
                              alignItems: "center",
                            }}
                            title={isRevealed ? "Hide" : "Reveal"}
                          >
                            {isRevealed ? <EyeOff size={13} /> : <Eye size={13} />}
                          </button>

                          <button
                            type="button"
                            onClick={() => handleCopy(cred.password, cred.id)}
                            style={{
                              background: isCopied ? "rgba(16, 185, 129, 0.2)" : "rgba(51, 65, 85, 0.5)",
                              border: "none",
                              borderRadius: "4px",
                              color: isCopied ? "#34d399" : "#94a3b8",
                              cursor: "pointer",
                              padding: "4px 6px",
                              display: "flex",
                              alignItems: "center",
                            }}
                            title="Copy password"
                          >
                            {isCopied ? <Check size={13} /> : <Copy size={13} />}
                          </button>
                        </div>
                      </div>
                    </div>

                    {/* Additional Notes */}
                    {cred.additionalInfo && (
                      <div style={{ borderTop: "1px solid rgba(30, 41, 59, 0.6)", paddingTop: "8px" }}>
                        <div style={{ fontSize: "11px", color: "#64748b", fontWeight: 600, textTransform: "uppercase" }}>
                          Additional Info &amp; Notes
                        </div>
                        <div style={{ fontSize: "12px", color: "#cbd5e1", marginTop: "2px", whiteSpace: "pre-wrap" }}>
                          {cred.additionalInfo}
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Card Footer */}
                  <div style={{ fontSize: "11px", color: "#64748b", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span>Updated: {new Date(cred.updatedAt).toLocaleDateString("en-ZA")}</span>
                    <span>By: {cred.updatedBy}</span>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div
            style={{
              padding: "40px",
              textAlign: "center",
              backgroundColor: "#090e17",
              borderRadius: "12px",
              border: "1px dashed rgba(51, 65, 85, 0.8)",
              color: "#64748b",
            }}
          >
            <KeyRound size={32} style={{ margin: "0 auto 12px", color: "#475569" }} />
            <div style={{ fontSize: "0.9375rem", fontWeight: 600, color: "#94a3b8" }}>
              {searchQuery ? "No matching credentials found." : "No credentials stored in the vault yet."}
            </div>
            <p style={{ fontSize: "0.8125rem", margin: "4px 0 0" }}>
              Use the form above to add your first database or service credential.
            </p>
          </div>
        )}
      </div>

      {/* System Infrastructure Diagnostics Table */}
      <div className={styles.panelCard} style={{ marginTop: "12px" }}>
        <div className={styles.panelHeader}>
          <h2>Core System Platform &amp; Infrastructure Information</h2>
          <p>Read-only environment and platform details</p>
        </div>
        <table className={styles.table}>
          <tbody>
            <tr>
              <td><strong>Application Environment</strong></td>
              <td>Production (Live Operations)</td>
            </tr>
            <tr>
              <td><strong>Hosting Platform</strong></td>
              <td>Vercel Edge Network</td>
            </tr>
            <tr>
              <td><strong>Database Provider</strong></td>
              <td>Supabase Postgres (Region: eu-west-1 / Ireland)</td>
            </tr>
            <tr>
              <td><strong>Email Provider</strong></td>
              <td>Resend Transactional API</td>
            </tr>
            <tr>
              <td><strong>Database Security Policy</strong></td>
              <td>Row Level Security (RLS) &amp; Superuser AES Vault Activated</td>
            </tr>
            <tr>
              <td><strong>Migration Version</strong></td>
              <td>00032_system_settings_control_centre.sql</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import { FormEvent, useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { Button } from "@/components/ui/Button";
import clsx from "clsx";
import page from "@/styles/Page.module.css";

type TrackingResult = {
  orderReference: string;
  status: "placed" | "processing" | "shipped" | "out_for_delivery" | "delivered";
  estimatedDelivery: string | null;
  courier: string | null;
  waybillNumber: string | null;
  updatedAt: string;
};

const TRACKING_STAGES = [
  { key: "placed", label: "Order Placed", desc: "Order received & verified" },
  { key: "processing", label: "Processing & Packed", desc: "Stationery kit assembled" },
  { key: "shipped", label: "Handed to Courier", desc: "In transit with courier" },
  { key: "out_for_delivery", label: "Out for Delivery", desc: "Arriving today" },
  { key: "delivered", label: "Delivered", desc: "Delivered & confirmed" },
] as const;

function getStageIndex(status: string): number {
  switch (status) {
    case "placed":
      return 0;
    case "processing":
      return 1;
    case "shipped":
      return 2;
    case "out_for_delivery":
      return 3;
    case "delivered":
      return 4;
    default:
      return 0;
  }
}

function formatDateDisplay(value: string | null): string {
  if (!value) return "To be confirmed";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-ZA", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });
}

export function TrackOrderForm() {
  const searchParams = useSearchParams();

  const [orderRef, setOrderRef] = useState("");
  const [email, setEmail] = useState("");
  const [uniqueId, setUniqueId] = useState("");

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [trackingData, setTrackingData] = useState<TrackingResult | null>(null);

  const executeLookup = async (params: { ref?: string; email?: string; uniqueId?: string; token?: string }) => {
    setLoading(true);
    setError(null);
    setTrackingData(null);

    const query = new URLSearchParams();
    if (params.ref) query.set("ref", params.ref);
    if (params.email) query.set("email", params.email);
    if (params.uniqueId) query.set("uniqueId", params.uniqueId);
    if (params.token) query.set("token", params.token);

    try {
      const res = await fetch(`/api/track-order?${query.toString()}`);
      const data = await res.json();

      if (!res.ok || !data.orderReference) {
        setError(
          data.message ||
            "Order tracking record not found. Please check your order reference and receipt details."
        );
        return;
      }

      setTrackingData(data);
      if (data.orderReference) setOrderRef(data.orderReference);
    } catch {
      setError("Unable to connect to order tracking service. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  // URL Auto-Fill & Execution on page mount
  useEffect(() => {
    const refParam = searchParams.get("ref") || "";
    const emailParam = searchParams.get("email") || "";
    const tokenParam = searchParams.get("token") || "";
    const uniqueIdParam = searchParams.get("uniqueId") || "";

    if (refParam) setOrderRef(refParam);
    if (emailParam) setEmail(emailParam);
    if (uniqueIdParam) setUniqueId(uniqueIdParam);

    if (tokenParam || (refParam && emailParam && uniqueIdParam)) {
      executeLookup({
        ref: refParam,
        email: emailParam,
        token: tokenParam,
        uniqueId: uniqueIdParam,
      });
    }
  }, [searchParams]);

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!orderRef.trim() || !email.trim() || !uniqueId.trim()) {
      setError("Please fill in Order Reference, Email Address, and Unique Customer ID.");
      return;
    }

    executeLookup({
      ref: orderRef.trim(),
      email: email.trim(),
      uniqueId: uniqueId.trim(),
    });
  };

  const currentStageIndex = trackingData ? getStageIndex(trackingData.status) : 0;

  return (
    <div style={{ maxWidth: 860, margin: "0 auto", display: "grid", gap: 32 }}>
      {/* Manual Search Form */}
      <form className={clsx(page.formCard, page.formStack)} onSubmit={handleSubmit}>
        <p className={page.kicker}>Guest Order Tracker</p>
        <h2>Track your stationery order</h2>
        <p style={{ fontSize: 14, color: "var(--pex-text-muted)", marginTop: -4 }}>
          Enter your receipt proof details below to check live order status without logging in.
        </p>

        <div style={{ display: "grid", gap: 16, gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", alignItems: "end" }}>
          <div style={{ display: "flex", flexDirection: "column", justifyContent: "flex-end", alignItems: "center" }}>
            <label htmlFor="trackOrderRef" style={{ fontWeight: 700, fontSize: 13, display: "block", marginBottom: 6, textAlign: "center" }}>
              Order Reference
            </label>
            <input
              id="trackOrderRef"
              name="ref"
              value={orderRef}
              onChange={(e) => setOrderRef(e.target.value)}
              placeholder="PEX-XXXXX"
              style={{ width: "100%", textAlign: "center" }}
              required
            />
          </div>

          <div style={{ display: "flex", flexDirection: "column", justifyContent: "flex-end", alignItems: "center" }}>
            <label htmlFor="trackEmail" style={{ fontWeight: 700, fontSize: 13, display: "block", marginBottom: 6, textAlign: "center" }}>
              Customer Email
            </label>
            <input
              id="trackEmail"
              name="email"
              type="email"
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="name@example.com"
              style={{ width: "100%", textAlign: "center" }}
              required
            />
          </div>

          <div style={{ display: "flex", flexDirection: "column", justifyContent: "flex-end", alignItems: "center" }}>
            <label htmlFor="trackUniqueId" style={{ fontWeight: 700, fontSize: 13, display: "block", marginBottom: 6, textAlign: "center" }}>
              Unique Customer ID
            </label>
            <input
              id="trackUniqueId"
              name="uniqueId"
              value={uniqueId}
              onChange={(e) => setUniqueId(e.target.value)}
              placeholder="CUST-XXXXX"
              style={{ width: "100%", textAlign: "center" }}
              required
            />
          </div>
        </div>

        <Button type="submit" disabled={loading} variant="primary" style={{ marginTop: 8 }}>
          {loading ? "Searching order status..." : "Track My Order"}
        </Button>

        {error && (
          <div
            role="alert"
            style={{
              marginTop: 12,
              padding: "14px 16px",
              borderRadius: 14,
              fontSize: 14,
              fontWeight: 600,
              background: "rgba(185, 28, 28, 0.08)",
              color: "var(--pex-error)",
              border: "1px solid rgba(185, 28, 28, 0.2)",
            }}
          >
            {error}
          </div>
        )}
      </form>

      {/* Loading Skeleton */}
      {loading && (
        <div style={{ background: "#ffffff", borderRadius: 24, padding: 32, border: "1px solid var(--pex-border)" }}>
          <div style={{ height: 24, width: 200, background: "#f1f5f9", borderRadius: 8, marginBottom: 24 }} />
          <div style={{ display: "flex", gap: 16, justifyContent: "space-between" }}>
            {[1, 2, 3, 4, 5].map((i) => (
              <div key={i} style={{ flex: 1, height: 48, background: "#f8fafc", borderRadius: 12 }} />
            ))}
          </div>
        </div>
      )}

      {/* Order Progress Visualization */}
      {trackingData && !loading && (
        <div
          style={{
            background: "#ffffff",
            borderRadius: 24,
            padding: 32,
            border: "1px solid var(--pex-border)",
            boxShadow: "0 12px 32px rgba(15,23,42,0.06)",
            display: "grid",
            gap: 28,
          }}
        >
          {/* Status Header */}
          <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-between", alignItems: "center", gap: 16 }}>
            <div>
              <span style={{ fontSize: 12, textTransform: "uppercase", letterSpacing: "0.5px", fontWeight: 800, color: "var(--pex-keppel)" }}>
                Live Tracking Proof Verified
              </span>
              <h3 style={{ margin: "4px 0 0", fontSize: 24, fontWeight: 800, color: "var(--pex-navy)" }}>
                Order #{trackingData.orderReference}
              </h3>
            </div>
            <div style={{ textAlign: "right" }}>
              <span style={{ fontSize: 13, color: "var(--pex-text-muted)", display: "block" }}>Estimated Delivery</span>
              <strong style={{ fontSize: 16, color: "var(--pex-primary)", fontWeight: 800 }}>
                {formatDateDisplay(trackingData.estimatedDelivery)}
              </strong>
            </div>
          </div>

          {/* Visual 5-Stage Stepper Graph */}
          <div style={{ margin: "12px 0" }}>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(5, 1fr)",
                gap: 8,
                position: "relative",
              }}
            >
              {TRACKING_STAGES.map((stage, idx) => {
                const isCompleted = idx < currentStageIndex;
                const isCurrent = idx === currentStageIndex;
                const isFuture = idx > currentStageIndex;

                return (
                  <div
                    key={stage.key}
                    style={{
                      display: "flex",
                      flexDirection: "column",
                      alignItems: "center",
                      textAlign: "center",
                      position: "relative",
                    }}
                  >
                    {/* Circle Badge */}
                    <div
                      style={{
                        width: 38,
                        height: 38,
                        borderRadius: "50%",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        fontWeight: 800,
                        fontSize: 15,
                        zIndex: 2,
                        transition: "all 0.3s ease",
                        background: isCompleted || isCurrent ? "var(--pex-keppel)" : "#e2e8f0",
                        color: isCompleted || isCurrent ? "#ffffff" : "#64748b",
                        boxShadow: isCurrent ? "0 0 0 4px rgba(33,158,155,0.25)" : "none",
                        transform: isCurrent ? "scale(1.1)" : "none",
                      }}
                    >
                      {isCompleted ? "✓" : idx + 1}
                    </div>

                    {/* Step Title */}
                    <span
                      style={{
                        fontSize: 13,
                        fontWeight: isCurrent ? 800 : isCompleted ? 700 : 600,
                        color: isCurrent ? "var(--pex-primary)" : isCompleted ? "#334155" : "#94a3b8",
                        marginTop: 10,
                        textAlign: "center",
                        lineHeight: 1.2,
                      }}
                    >
                      {stage.label}
                    </span>

                    {/* Step Description */}
                    <span
                      style={{
                        fontSize: 11,
                        color: "#94a3b8",
                        marginTop: 4,
                        textAlign: "center",
                      }}
                    >
                      {stage.desc}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Courier Details Card */}
          {trackingData.courier || trackingData.waybillNumber ? (
            <div
              style={{
                background: "#f8fafc",
                borderRadius: 16,
                padding: 20,
                border: "1px solid #e2e8f0",
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "space-between",
                gap: 16,
              }}
            >
              <div>
                <span style={{ fontSize: 12, textTransform: "uppercase", fontWeight: 700, color: "#64748b" }}>
                  Logistics Partner &amp; Waybill
                </span>
                <p style={{ margin: "4px 0 0", fontSize: 16, fontWeight: 800, color: "#0f172a" }}>
                  {trackingData.courier || "Pexpacks Courier Network"}
                </p>
              </div>

              {trackingData.waybillNumber ? (
                <div>
                  <span style={{ fontSize: 12, color: "#64748b", display: "block" }}>Waybill Reference</span>
                  <a
                    href={`https://thecourierguy.co.za/tracking?waybill=${encodeURIComponent(trackingData.waybillNumber)}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={{
                      display: "inline-block",
                      marginTop: 2,
                      fontSize: 15,
                      fontWeight: 800,
                      color: "var(--pex-keppel)",
                      textDecoration: "underline",
                    }}
                  >
                    {trackingData.waybillNumber} ↗
                  </a>
                </div>
              ) : null}
            </div>
          ) : (
            <div
              style={{
                background: "#f0fbfa",
                borderRadius: 16,
                padding: 16,
                border: "1px solid #cdeeea",
                fontSize: 13,
                color: "#1a7a77",
                fontWeight: 600,
              }}
            >
